(99904,'wpcode_snippets','a:3:{s:10:\"everywhere\";a:1:{i:0;a:12:{s:2:\"id\";i:4102;s:5:\"title\";s:13:\"ac8_functions\";s:4:\"code\";s:1611:\"function creatorPagDELETE(){\r\n	echo <<<EOD\r\n		<div id=\"sc_title_main_portfolio\">\r\n			<div class=\"mainframe\">\r\n				<h1>Beneficios de la Levadura de Cerveza en el Alimento para mascotas</h1>\r\n				<p><b>Potencia la Vitalidad:</b> El Aporte Nutricional de la Levadura de Cerveza en la Alimentación para Mascotas</p>\r\n			</div>\r\n		</div>\r\n	EOD;\r\n	\r\n	\r\n	echo <<<EOD\r\n		<div id=\"sc_portada_main_portfolio\">\r\n			<div class=\"mainframe\">\r\n				<img src=\"https://picsum.photos/1920/1080?random=10\" alt=\"\">\r\n			</div>\r\n		</div>\r\n	EOD;\r\n	\r\n	echo <<<EOD\r\n		<div id=\"sc_keycolumns_main_portfolio\">\r\n			<div class=\"mainframe\">\r\n			\r\n				<div class=\"frame\">\r\n					<h2>Palatabilidad Aumentada</h2>\r\n					<p>La levadura de cerveza, clave en la creación de palatantes, eleva la aceptación alimentaria.</p>\r\n					<div class=\"img_frame\" alt>\r\n						<img src=\"https://picsum.photos/500/500?random=1\" alt=\"\">\r\n					</div>\r\n				</div>\r\n				\r\n				<div class=\"frame\">\r\n					<h2>Nuestro Compromiso en la Elaboración</h2>\r\n					<p>Sumergimos nuestras manos en la creación de palatantes, donde la levadura desempeña un papel esencial.</p>\r\n					<div class=\"img_frame\" alt>\r\n						<img src=\"https://picsum.photos/500/500?random=2\" alt=\"\">\r\n					</div>\r\n				</div>\r\n				\r\n				<div class=\"frame\">\r\n					<h2>Sabores Naturales para una Óptima Salud</h2>\r\n					<p>Exploramos cómo nuestra levadura enriquece los palatantes, asegurando deliciosos sabores y el bienestar animal.</p>\r\n					<div class=\"img_frame\" alt>\r\n						<img src=\"https://picsum.photos/500/500?random=3\" alt=\"\">\r\n					</div>\r\n				</div>\r\n				\r\n			</div>\r\n		</div>\r\n	EOD;\r\n}\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}}}s:16:\"site_wide_header\";a:4:{i:0;a:12:{s:2:\"id\";i:3989;s:5:\"title\";s:18:\"nav_bar_portafolio\";s:4:\"code\";s:791:\"echo \"<div class=\'scp_nvp12\'>\r\n		<div class=\'frame\'>\r\n		</div>\r\n	</div>\";\r\n\r\n	$conex = mysqli_connect(\'localhost\',\'48fdda17a8\',\'6677ecbae566c4617d59\',\'993.c2a.mywebsitetransfer.com_1665427950\');\r\n	$conex->set_charset(\'utf8\');\r\n\r\n	$sql = mysqli_query($conex,\"SELECT * FROM carrusel_home\");\r\n	\r\n	while($row = mysqli_fetch_assoc($sql)) {\r\n		$portItem = $row[\'nombre\'];\r\n		$itemHref = $row[\'enlace\'];\r\n		\r\n		//echo $itemHref.\"<br>\";\r\n		\r\n		echo \"<script>\r\n				function portfolioNavBar() {\r\n					const navBar = document.querySelector(\'.scp_nvp12 > .frame\');\r\n					console.log(navBar);\r\n					const item = document.createElement(\'a\');\r\n				\r\n					item.innerHTML = \'$portItem\';\r\n					item.href = \'$itemHref\';\r\n				\r\n					navBar.appendChild(item);\r\n				};\r\n				portfolioNavBar();\r\n			</script>\";\r\n	};\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:16:\"site_wide_header\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:1;s:5:\"rules\";a:2:{s:4:\"show\";s:4:\"show\";s:6:\"groups\";a:1:{i:0;a:3:{i:0;a:4:{s:4:\"type\";s:4:\"page\";s:6:\"option\";s:12:\"type_of_page\";s:8:\"relation\";s:1:\"=\";s:5:\"value\";s:9:\"is_single\";}i:1;a:4:{s:4:\"type\";s:4:\"page\";s:6:\"option\";s:9:\"post_type\";s:8:\"relation\";s:2:\"!=\";s:5:\"value\";s:4:\"post\";}i:2;a:4:{s:4:\"type\";s:4:\"page\";s:6:\"option\";s:12:\"type_of_page\";s:8:\"relation\";s:2:\"!=\";s:5:\"value\";s:13:\"is_front_page\";}}}}s:8:\"priority\";i:11;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}}i:1;a:12:{s:2:\"id\";i:3953;s:5:\"title\";s:18:\"bootstrap_a_header\";s:4:\"code\";s:347:\"<!-- Boostrap grid -->\r\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/bootstrap-v4-grid-only@1.0.0/dist/bootstrap-grid.min.css\" />\r\n\r\n<!-- Swiper -->\r\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/swiper@10/swiper-bundle.min.css\" />\r\n<script src=\"https://cdn.jsdelivr.net/npm/swiper@10/swiper-bundle.min.js\" defer></script>\";s:9:\"code_type\";s:4:\"html\";s:8:\"location\";s:16:\"site_wide_header\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}}i:2;a:12:{s:2:\"id\";i:3772;s:5:\"title\";s:25:\"menu_categorias_articulos\";s:4:\"code\";s:3212:\"echo \"<div class=\'scp_cm1\'>\r\n		<div class=\'container\'>\r\n			<a class=\'movil_sec_head\'>\r\n				Categorías\r\n				<img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/up-arrow-angle-1.png\' alt=\'\'/>\r\n			</a>\r\n		</div>\r\n	</div>\r\n	<script>\r\n		function movilCategory(){\r\n			const menuContainer = document.querySelector(\'.scp_cm1 > .container\');\r\n			const btnCategorias = document.querySelector(\'.movil_sec_head\');\r\n			const arrowBtn = document.querySelector(\'.movil_sec_head > img\');\r\n			\r\n			btnCategorias.addEventListener(\'click\',()=>{\r\n				arrowBtn.style.transform != \'rotate(0deg)\' ? arrowBtn.style.transform = \'rotate(0deg)\' : arrowBtn.style.transform = \'rotate(180deg)\';\r\n				menuContainer.style.maxHeight == \'1000px\' ? menuContainer.style.transition = \'ease-in-out .7s\' : menuContainer.style.transition = \'ease-in-out 1s\';\r\n				menuContainer.style.maxHeight == \'1000px\' ? menuContainer.style.maxHeight = \'max(10vw,30px)\' : menuContainer.style.maxHeight = \'1000px\';\r\n			})\r\n			\r\n			const mediaQuery = matchMedia(\'only screen and (max-width: 1080px)\');\r\n			mediaQuery.matches == false ? menuContainer.style.maxHeight == \'1000px\' : menuContainer.style.maxHeight = \'max(10vw,30px)\';\r\n			mediaQuery.matches == false ? btnCategorias.style.display = \'none\' : btnCategorias.style.display = \'flex\';\r\n			\r\n			mediaQuery.addListener(() => {\r\n				mediaQuery.matches == false ? menuContainer.style.maxHeight == \'1000px\' : menuContainer.style.maxHeight = \'max(10vw,30px)\';\r\n				mediaQuery.matches == false ? btnCategorias.style.display = \'none\' : btnCategorias.style.display = \'flex\';\r\n			});\r\n		};\r\n		movilCategory();\r\n	</script>\r\n\";		\r\n	$conex = mysqli_connect(\'localhost\',\'48fdda17a8\',\'6677ecbae566c4617d59\',\'993.c2a.mywebsitetransfer.com_1665427950\');\r\n	$conex->set_charset(\'utf8\');\r\n	\r\n	$consulta = mysqli_query($conex, \"SELECT * FROM wp_term_taxonomy WHERE taxonomy = \'category\' \");\r\n	while($fila = mysqli_fetch_assoc($consulta)) {\r\n		\r\n		$termID = $fila[\'term_id\'];\r\n		\r\n		$consulta2 = mysqli_query($conex, \"SELECT name FROM wp_terms WHERE term_id = \'$termID\' LIMIT 1\");\r\n		$termName = mysqli_num_rows($consulta2) > 0 ? mysqli_fetch_assoc($consulta2)[\'name\'] : \'\';\r\n		\r\n		$link = substr($_SERVER[REQUEST_URI],1,-1);\r\n		$query3 = mysqli_query($conex, \"SELECT ID FROM wp_posts WHERE post_name = \'$link\' LIMIT 1\");\r\n		$currentPostID = mysqli_num_rows($query3) > 0 ? mysqli_fetch_assoc($query3)[\'ID\'] : \'\';\r\n		\r\n		$currentCat = \'none\';\r\n		\r\n		$query4 = mysqli_query($conex, \"SELECT * FROM wp_term_relationships WHERE object_id = \'$currentPostID\' \");\r\n		if (mysqli_num_rows($query4) > 0) {\r\n			while($taxNumber = mysqli_fetch_assoc($query4)){\r\n				if($termID === $taxNumber[\'term_taxonomy_id\']) {\r\n					$currentCat = \'currentCategory\';\r\n				};\r\n			};\r\n		};\r\n		//echo $currentPostID;\r\n		\r\n		echo \"<script>\r\n				function appendCategorys(){\r\n					const categoryContainer = document.querySelector(\'.scp_cm1 > .container:nth-of-type(1)\');\r\n					const categItem = document.createElement(\'a\');\r\n					\r\n					categItem.classList.add(\'$currentCat\');\r\n					categItem.innerHTML = \'$termName\';\r\n					categItem.href = \'\'\r\n					categoryContainer.appendChild(categItem);\r\n				};\r\n				appendCategorys();\r\n			</script>\";\r\n	};\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:16:\"site_wide_header\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:1;s:5:\"rules\";a:2:{s:4:\"show\";s:4:\"show\";s:6:\"groups\";a:1:{i:0;a:2:{i:0;a:4:{s:4:\"type\";s:4:\"page\";s:6:\"option\";s:9:\"post_type\";s:8:\"relation\";s:1:\"=\";s:5:\"value\";s:4:\"post\";}i:1;a:4:{s:4:\"type\";s:4:\"page\";s:6:\"option\";s:12:\"type_of_page\";s:8:\"relation\";s:2:\"!=\";s:5:\"value\";s:13:\"is_front_page\";}}}}s:8:\"priority\";i:11;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}}i:3;a:12:{s:2:\"id\";i:3721;s:5:\"title\";s:14:\"menu_articulos\";s:4:\"code\";s:2968:\"echo \"<div class=\'scp_m2\'>\r\n		<a class=\'container\' href=\'https://suministrossustentables.com/\'>\r\n			<img src=\'https://suministrossustentables.com/wp-content/uploads/2023/06/logo_green_white-e1685736789208.png\' alt=\'\'/>\r\n		</a>\r\n		<img class=\'articles_burger_menu\' src=\'https://suministrossustentables.com/wp-content/uploads/2023/06/burger-bar-1.png\' alt=\'\'/>\r\n		<img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/Banner_Articulo_SUCCESS-3-e1688677647639.png\' alt=\'\'/>\r\n		<div class=\'menu_movil\'>\r\n			<a href=\'https://suministrossustentables.com/\'><img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/Perfil-Facebook-SUCCES.png\' alt/></a>\r\n			<a href=\'https://suministrossustentables.com/\'><img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/home.png\' alt=\'\'/>Inicio</a>\r\n			<a href=\'\'><img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/group.png\' alt=\'\'/>Nosotros</a>\r\n			<a href=\'\'><img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/shopping-bag.png\' alt=\'\'/>Producto</a>\r\n			<a ><img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/chat.png\' alt=\'\'/>Contacto</a>\r\n			\r\n			<div class=\'social\'>\r\n			 <a href=\'\'><img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/024-facebook.png\' alt=\'\'/></a>\r\n			 <a href=\'\'><img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/022-instagram.png\' alt=\'\'/></a>\r\n			 <a href=\'\'><img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/035-whatsapp.png\' alt=\'\'/></a>\r\n			 <a href=\'\'><img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/034-linkedin.png\' alt=\'\'/></a>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<script>\r\n		function displayMenu(){\r\n			const btnBurger = document.querySelector(\'.scp_m2 > img:nth-of-type(1)\');\r\n			const movilMenu = document.querySelector(\'.menu_movil\');\r\n			const body = document.querySelector(\'body\');\r\n			\r\n			btnBurger.addEventListener(\'click\',()=>{\r\n				if(movilMenu.style.left == \'0%\') {\r\n					movilMenu.style.left = \'-100%\';\r\n					body.style.overflow = \'initial\';\r\n					btnBurger.src = \'https://suministrossustentables.com/wp-content/uploads/2023/06/burger-bar-1.png\'\r\n				} else {\r\n					movilMenu.style.display = \'flex\';\r\n					movilMenu.style.left = \'0%\';\r\n					body.style.overflow = \'hidden\';\r\n					btnBurger.src = \'https://suministrossustentables.com/wp-content/uploads/2023/07/left-2.png\'\r\n				};\r\n			});\r\n				\r\n			body.addEventListener(\'click\',(e)=>{\r\n				const trg1 = e.target.closest(\'.menu_movil\') != null ? \'menu_movil\' : null;\r\n				const btn = e.target.className\r\n				//console.log(trg1)\r\n				\r\n				if( trg1 != \'menu_movil\' && btn != \'articles_burger_menu\') {\r\n					movilMenu.style.left = \'-100%\';\r\n					body.style.overflow = \'initial\';\r\n					btnBurger.src = \'https://suministrossustentables.com/wp-content/uploads/2023/06/burger-bar-1.png\'\r\n				}\r\n			});\r\n		};\r\n		displayMenu();\r\n	</script>\r\n	\";\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:16:\"site_wide_header\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:1;s:5:\"rules\";a:2:{s:4:\"show\";s:4:\"show\";s:6:\"groups\";a:1:{i:0;a:2:{i:0;a:4:{s:4:\"type\";s:4:\"page\";s:6:\"option\";s:12:\"type_of_page\";s:8:\"relation\";s:1:\"=\";s:5:\"value\";s:9:\"is_single\";}i:1;a:4:{s:4:\"type\";s:4:\"page\";s:6:\"option\";s:12:\"type_of_page\";s:8:\"relation\";s:2:\"!=\";s:5:\"value\";s:13:\"is_front_page\";}}}}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}}}s:16:\"site_wide_footer\";a:2:{i:0;a:12:{s:2:\"id\";i:3184;s:5:\"title\";s:17:\"Carusel_Seccion_2\";s:4:\"code\";s:1186:\"function autoScrollFooterCarousel(){\r\n	//alert(\"Snipet funcionando\");\r\n	\r\n	const carouselContainer = document.querySelector(\'.sd_carousel\');\r\n	const reel = document.querySelector(\'.sd_reel\');\r\n 	const slides = Array.from(reel.children);\r\n	console.log(slides);\r\n	let slideObj = [];\r\n	\r\n	let i = 0\r\n	let x= 0\r\n	\r\n	function slideProt(index, offsetLeft, width) {\r\n		this.index = index;\r\n		this.offsetLeft = offsetLeft;\r\n		this.width = width;\r\n		this.marginLeft = offsetLeft - (width / 2);\r\n		this.marginRight = offsetLeft + (width / 2);\r\n	};\r\n	\r\n	slides.forEach(slide=>{\r\n		slideObj[x] = new slideProt(i, slide.offsetLeft + (-(slides[0].offsetLeft)), slide.offsetWidth);			\r\n		x++\r\n		i++\r\n	});\r\n	\r\n	\r\n	\r\n	\r\n	let q = 1;\r\n	let intervalReelLoop =\"\"\r\n	\r\n	function reelAutoRun () { //Funcion para recorrer automaticamente el reel	\r\n		intervalReelLoop = setInterval(()=>{\r\n			if(q < 3){ \r\n				carouselContainer.scrollTo({\r\n					left: slideObj[q].offsetLeft,\r\n					behavior: \'smooth\'\r\n				});\r\n				q++\r\n			} else {\r\n				q = 0\r\n				carouselContainer.scrollTo({\r\n					left: 0,\r\n					behavior: \'smooth\'\r\n				});\r\n				q++\r\n			};		\r\n		},3500)\r\n	};\r\n	reelAutoRun()\r\n	\r\n	\r\n}\r\n\r\nautoScrollFooterCarousel()\";s:9:\"code_type\";s:2:\"js\";s:8:\"location\";s:16:\"site_wide_footer\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:1;s:5:\"rules\";a:2:{s:4:\"show\";s:4:\"show\";s:6:\"groups\";a:1:{i:0;a:1:{i:0;a:4:{s:4:\"type\";s:4:\"page\";s:6:\"option\";s:12:\"type_of_page\";s:8:\"relation\";s:1:\"=\";s:5:\"value\";s:13:\"is_front_page\";}}}}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}}i:1;a:12:{s:2:\"id\";i:2606;s:5:\"title\";s:17:\"Carusel_Seccion_1\";s:4:\"code\";s:1187:\"function autoScrollHomeCarousel(){\r\n	//alert(\"Snipet funcionando\");\r\n	\r\n	const carouselContainer = document.querySelector(\'.sa_carousel_home\');\r\n	const reel = document.querySelector(\'.sa_reel\');\r\n 	const slides = Array.from(reel.children);\r\n	console.log(slides);\r\n	let slideObj = [];\r\n	\r\n	let i = 0\r\n	let x= 0\r\n	\r\n	function slideProt(index, offsetLeft, width) {\r\n		this.index = index;\r\n		this.offsetLeft = offsetLeft;\r\n		this.width = width;\r\n		this.marginLeft = offsetLeft - (width / 2);\r\n		this.marginRight = offsetLeft + (width / 2);\r\n	};\r\n	\r\n	slides.forEach(slide=>{\r\n		slideObj[x] = new slideProt(i, slide.offsetLeft + (-(slides[0].offsetLeft)), slide.offsetWidth);			\r\n		x++\r\n		i++\r\n	});\r\n	\r\n	\r\n	\r\n	\r\n	let q = 1;\r\n	let intervalReelLoop =\"\"\r\n	\r\n	function reelAutoRun () { //Funcion para recorrer automaticamente el reel	\r\n		intervalReelLoop = setInterval(()=>{\r\n			if(q < 4){ \r\n				carouselContainer.scrollTo({\r\n					left: slideObj[q].offsetLeft,\r\n					behavior: \'smooth\'\r\n				});\r\n				q++\r\n			} else {\r\n				q = 0\r\n				carouselContainer.scrollTo({\r\n					left: 0,\r\n					behavior: \'smooth\'\r\n				});\r\n				q++\r\n			};		\r\n		},3500)\r\n	};\r\n	reelAutoRun()\r\n	\r\n	\r\n}\r\n\r\nautoScrollHomeCarousel()\";s:9:\"code_type\";s:2:\"js\";s:8:\"location\";s:16:\"site_wide_footer\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:1;s:5:\"rules\";a:2:{s:4:\"show\";s:4:\"show\";s:6:\"groups\";a:1:{i:0;a:1:{i:0;a:4:{s:4:\"type\";s:4:\"page\";s:6:\"option\";s:12:\"type_of_page\";s:8:\"relation\";s:1:\"=\";s:5:\"value\";s:13:\"is_front_page\";}}}}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}}}}','yes'),
