(3551,1,'2023-07-02 18:12:01','2023-07-02 18:12:01','echo \" <div class=\'scp_p12\'>\r\n			<div class=\'container\'>\r\n			</div>\r\n		</div>\";\r\n\r\n	$conex = mysqli_connect(\"localhost\",\"48fdda17a8\",\"6677ecbae566c4617d59\",\"993.c2a.mywebsitetransfer.com_1665427950\");\r\n	$conex->set_charset(\"utf8\");\r\n	\r\n	$consulta = \'SELECT * FROM wp_posts WHERE post_type = \"post\" and post_status = \"publish\" ORDER BY post_date DESC LIMIT 5\';\r\n	$resultado = mysqli_query($conex, $consulta);\r\n	$numResultados = mysqli_num_rows($resultado);\r\n\r\n	if($numResultados > 0) {\r\n		while ($fila = mysqli_fetch_assoc($resultado)){\r\n			\r\n			$postID = $fila[\'ID\'];\r\n			$postTitle = $fila[\'post_title\'];\r\n			$postExcerpt = substr($fila[\"post_excerpt\"],0,180).\'...\';\r\n			$postDate = date(\'d / M / Y\', strtotime($fila[\"post_date\"]));\r\n			$postGuid = \'https://suministrossustentables.com/\'.$fila[\"post_name\"];\r\n			\r\n			$consultaThumbnail = \"SELECT * FROM wp_postmeta WHERE post_id=$postID and meta_key=\'_thumbnail_id\' LIMIT 1\";\r\n			$resThumbnail = mysqli_query($conex, $consultaThumbnail);\r\n			$thumbnailResultado = mysqli_num_rows($resThumbnail);\r\n		\r\n			if($thumbnailResultado > 0) {\r\n				$filaThumb = mysqli_fetch_assoc($resThumbnail);\r\n				$thumbnailID = $filaThumb[\"meta_value\"];\r\n			\r\n				$consultaSrc = \"SELECT guid FROM wp_posts WHERE ID=$thumbnailID LIMIT 1\";\r\n				$resSrc = mysqli_query($conex, $consultaSrc);\r\n			\r\n				$filaSrc = mysqli_fetch_assoc($resSrc);\r\n				$thumbURL = $filaSrc[\"guid\"];				\r\n				//echo \"$thumbURL\";\r\n	\r\n				} else {\r\n					$thumbURL = \"https://picsum.photos/1200/720?random=3\";\r\n				};\r\n			\r\n			\r\n			echo \"<script>\r\n				function createItem() {\r\n					const galeryContainer = document.querySelector(\'.scp_p12 > .container\');\r\n					const galeryItem = document.createElement(\'div\');\r\n					const itemImg = document.createElement(\'img\');\r\n					const itemH2 = document.createElement(\'h2\');\r\n					const itemDate = document.createElement(\'h3\');\r\n					const itemExcerpt = document.createElement(\'p\');\r\n					const itemHref = document.createElement(\'a\');\r\n					\r\n					itemImg.src = \'$thumbURL\';\r\n					itemH2.innerHTML = \'$postTitle\';\r\n					itemDate.innerHTML = \'$postDate\';\r\n					itemExcerpt.innerHTML = \'$postExcerpt\';\r\n					itemHref.href = \'$postGuid\';\r\n				\r\n					galeryItem.classList.add(\'item\');\r\n					galeryItem.appendChild(itemImg);\r\n					galeryItem.appendChild(itemH2);\r\n					galeryItem.appendChild(itemExcerpt);\r\n					galeryItem.appendChild(itemDate);\r\n					galeryItem.appendChild(itemHref);\r\n					\r\n					galeryContainer.appendChild(galeryItem);\r\n				}\r\n				createItem();\r\n				</script>\";\r\n		};\r\n	};','latest_post_galery','','publish','closed','closed','','latest_post_preview','','','2024-02-26 21:47:15','2024-02-26 21:47:15','',0,'https://suministrossustentables.com/?post_type=wpcode&#038;p=3551',0,'wpcode','',0),
