(2605,1,'2024-02-26 21:32:45','2024-02-26 21:32:45','add_action(\'admin_init\', function () {\r\n    // Redirect any user trying to access comments page\r\n    global $pagenow;\r\n    \r\n    if ($pagenow === \'edit-comments.php\') {\r\n        wp_safe_redirect(admin_url());\r\n        exit;\r\n    }\r\n\r\n    // Remove comments metabox from dashboard\r\n    remove_meta_box(\'dashboard_recent_comments\', \'dashboard\', \'normal\');\r\n\r\n    // Disable support for comments and trackbacks in post types\r\n    foreach (get_post_types() as $post_type) {\r\n        if (post_type_supports($post_type, \'comments\')) {\r\n            remove_post_type_support($post_type, \'comments\');\r\n            remove_post_type_support($post_type, \'trackbacks\');\r\n        }\r\n    }\r\n});\r\n\r\n// Close comments on the front-end\r\nadd_filter(\'comments_open\', \'__return_false\', 20, 2);\r\nadd_filter(\'pings_open\', \'__return_false\', 20, 2);\r\n\r\n// Hide existing comments\r\nadd_filter(\'comments_array\', \'__return_empty_array\', 10, 2);\r\n\r\n// Remove comments page in menu\r\nadd_action(\'admin_menu\', function () {\r\n    remove_menu_page(\'edit-comments.php\');\r\n});\r\n\r\n// Remove comments links from admin bar\r\nadd_action(\'init\', function () {\r\n    if (is_admin_bar_showing()) {\r\n        remove_action(\'admin_bar_menu\', \'wp_admin_bar_comments_menu\', 60);\r\n    }\r\n});','Completely Disable Comments','','trash','closed','closed','','__trashed','','','2024-02-26 21:32:45','2024-02-26 21:32:45','',0,'https://suministrossustentables.com/?post_type=wpcode&#038;p=2605',0,'wpcode','',0),
(2606,1,'2023-06-02 19:41:13','2023-06-02 19:41:13','function autoScrollHomeCarousel(){\r\n	//alert(\"Snipet funcionando\");\r\n	\r\n	const carouselContainer = document.querySelector(\'.sa_carousel_home\');\r\n	const reel = document.querySelector(\'.sa_reel\');\r\n 	const slides = Array.from(reel.children);\r\n	console.log(slides);\r\n	let slideObj = [];\r\n	\r\n	let i = 0\r\n	let x= 0\r\n	\r\n	function slideProt(index, offsetLeft, width) {\r\n		this.index = index;\r\n		this.offsetLeft = offsetLeft;\r\n		this.width = width;\r\n		this.marginLeft = offsetLeft - (width / 2);\r\n		this.marginRight = offsetLeft + (width / 2);\r\n	};\r\n	\r\n	slides.forEach(slide=>{\r\n		slideObj[x] = new slideProt(i, slide.offsetLeft + (-(slides[0].offsetLeft)), slide.offsetWidth);			\r\n		x++\r\n		i++\r\n	});\r\n	\r\n	\r\n	\r\n	\r\n	let q = 1;\r\n	let intervalReelLoop =\"\"\r\n	\r\n	function reelAutoRun () { //Funcion para recorrer automaticamente el reel	\r\n		intervalReelLoop = setInterval(()=>{\r\n			if(q < 4){ \r\n				carouselContainer.scrollTo({\r\n					left: slideObj[q].offsetLeft,\r\n					behavior: \'smooth\'\r\n				});\r\n				q++\r\n			} else {\r\n				q = 0\r\n				carouselContainer.scrollTo({\r\n					left: 0,\r\n					behavior: \'smooth\'\r\n				});\r\n				q++\r\n			};		\r\n		},3500)\r\n	};\r\n	reelAutoRun()\r\n	\r\n	\r\n}\r\n\r\nautoScrollHomeCarousel()','Carusel_Seccion_1','','publish','closed','closed','','untitled-snippet','','','2024-02-26 21:47:18','2024-02-26 21:47:18','',0,'https://suministrossustentables.com/wpcode/untitled-snippet/',0,'wpcode','',0),
