(2962,1,'2023-06-03 14:29:34','2023-06-03 14:29:34','','SUCCESS_icon_web (1)','','inherit','open','closed','','success_icon_web-1','','','2023-06-03 14:29:34','2023-06-03 14:29:34','',0,'https://suministrossustentables.com/wp-content/uploads/2023/06/SUCCESS_icon_web-1.png',0,'attachment','image/png',0),
(3629,1,'2023-07-05 01:56:14','2023-07-05 01:56:14','echo \"<div class=\'scp_bl1\'>\r\n		<article>\r\n			<div class=\'header\'>\r\n				<div class=\'ornament\'></div>\r\n				<h2>Entradas Recientes</h2>\r\n			</div>\r\n		</article>\r\n	</div>\";\r\n\r\n	$conex = mysqli_connect(\'localhost\',\'48fdda17a8\',\'6677ecbae566c4617d59\',\'993.c2a.mywebsitetransfer.com_1665427950\');\r\n	$conex->set_charset(\'utf8\');\r\n\r\n	$consulta = mysqli_query($conex, \'SELECT * FROM wp_posts WHERE post_type = \"post\" and post_status = \"publish\" ORDER BY post_date DESC LIMIT 6\');\r\n	$numRows = mysqli_num_rows($consulta);\r\n\r\n	if($numRows > 0){\r\n		while($fila = mysqli_fetch_assoc($consulta)){\r\n			$postGuid = \'https://suministrossustentables.com/\'.$fila[\'post_name\'];\r\n			\r\n			//Encontrar la URL que muestra el explorador para saber la URL del Post en el que se encuentra\r\n			$link = (isset($_SERVER[\'HTTPS\']) && $_SERVER[\'HTTPS\'] === \'on\' ? \"https\" : \"http\") . \"://$_SERVER[HTTP_HOST]$_SERVER[REQUEST_URI]\";\r\n			\r\n			if($postGuid.\'/\' != $link) {\r\n				\r\n				\r\n				$postID = $fila[\'ID\'];\r\n				$postTitle = $fila[\'post_title\'];\r\n				$postExcerpt = substr($fila[\'post_excerpt\'],0,50).\'...\';\r\n				\r\n				//echo $postGuid;\r\n				\r\n				$consulta2 = mysqli_query($conex, \"SELECT * FROM wp_postmeta WHERE post_id=$postID and meta_key=\'_thumbnail_id\' LIMIT 1\");\r\n				$thumbnailID = mysqli_num_rows($consulta2) > 0 ? mysqli_fetch_assoc($consulta2)[\'meta_value\'] : \'\'; \r\n				\r\n				$consulta3 = mysqli_query($conex, \"SELECT guid FROM wp_posts WHERE ID=$thumbnailID LIMIT 1\");\r\n				$postImgURL = mysqli_num_rows($consulta3) > 0 ? mysqli_fetch_assoc($consulta3)[\'guid\'] : \'\';\r\n				\r\n				//echo $postImgURL.\"<br>\";\r\n				\r\n				echo \"<script>\r\n						function createItemLatBar(){\r\n							const article = document.querySelector(\'.scp_bl1 > article:nth-of-type(1)\');\r\n							const infoContainer = document.createElement(\'article\');\r\n							const item = document.createElement(\'div\');\r\n							const postImg = document.createElement(\'img\');\r\n							const postTitle = document.createElement(\'h2\');\r\n							const postExcerpt = document.createElement(\'p\');\r\n							const postHref = document.createElement(\'a\');\r\n							\r\n							postImg.src = \'$postImgURL\';\r\n							postTitle.innerHTML = \'$postTitle\';\r\n							postExcerpt.innerHTML = \'$postExcerpt\';\r\n							postHref.href = \'$postGuid\';\r\n						\r\n							infoContainer.appendChild(postTitle);\r\n							infoContainer.appendChild(postExcerpt);\r\n							\r\n							item.classList.add(\'item\');\r\n							item.appendChild(postImg);\r\n							item.appendChild(infoContainer);\r\n							item.appendChild(postHref);\r\n						\r\n							article.appendChild(item);\r\n						};\r\n						createItemLatBar();\r\n						</script>\";\r\n			};\r\n		};\r\n	};','articulo_ultimos_post_barra_lateral','','publish','closed','closed','','articulo_barra_lateral','','','2024-02-26 21:47:12','2024-02-26 21:47:12','',0,'https://suministrossustentables.com/wpcode/articulo_barra_lateral/',0,'wpcode','',0),
