:absolute;\n	top:0;\n	left:25%;\n	transform:translatex(-50%);\n	height:70%;\n	aspect-ratio:6 / 4;\n	display:flex;\n	flex-direction:column;\n	justify-content:end;\n	align-items:center;\n	background-color:RGBA(0,0,0,0);\n		animation: fadeInOut 15s infinite;\n}\n\n.sab1_info_container > h2{\n	margin:0!important;\n	color:#9DF22F;\n	font-family:playfair display;\n	font-style:italic;\n	font-weight:500;\n	width:60%;\n	font-size:max(3vw,38px)\n}\n\n.sab1_info_container > p {\n	margin:1% 0!important;\n	padding:0!important;\n	width:60%;\n	color:white;\n	line-height:1.5;\n	font-size:max(.7vw,11px);\n}\n\n@keyframes fadeInOut {\n	from {opacity: 1;\n				left:25%}\n	50% {opacity: 1;\n			left:25%}\n	55% {opacity: 0;\n			left:50%}\n	95% {opacity:0;\n			left:50%}\n	to {opacity: 1;\n			left:25%}\n}\n\n.sa_block_1 > .slogan {\n	width:100%!important;\n	position:absolute;\n	top:93%;\n	animation: sloganreel 12s infinite linear;\n}\n\n@keyframes sloganreel {\n	from { left:-50%}\n	to {left:100%}\n}\n\n.sa_block_1 > .slogan > h2 {\n	width:100%;\n	color:white;\n	font-family:Playfair Display;\n	font-style:italic;\n	font-weight:500;\n	font-size:max(1.5vw,19px);\n}\n\n\n.sa_block_2 {\n	position:relative;\n	width:100%;\n	height:30%;\n	background-color:white;\n	display:flex;\n	justify-content:space-between;\n	padding:2% 12%;\n}\n\n.sab2_info_container {\n	width:30%;\n	padding:2%;\n}\n\n.sab2_title_container{\n	display:flex;\n	height:20%;\n	j2ustify-content:c;\n	align-items:center;\n	margin-bottom:5%;\n}\n\n.sab2_title_container > img {\n	height:50%;\n	object-fit:contain;\n}\n\n.sab2_title_container > h2 {\n	font-size: max(1.2vw,16px);\n	margin:0 2%!important;\n}\n\n.sab2_info_container > p {\n	font-size: max(.8vw, 11px);\n	line-height:1.5;\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>> SECTION B*/\n\n.section_b {\n	position:relative;\n	margin:0!important;\n	padding:4% 12% 4%;\n	background-color:whitesmoke;\n	width:100vw;\n	min-width:1280px;\n	display:flex;\n}\n\n.section