t:contain;\n	opacity:.3;\n}\n\n.sc_title_container > h2 {\n	margin:0!important;\n	position:relative;\n	font-weight:500;\n	font-size:max(2.2vw, 35px);\n	opacity:.8;\n	font-family:Playfair display;\n	line-height:1.1;\n	text-align:center;\n}\n\n.sc_portfolio_container {\n	padding:7% 0;\n	position:relative;\n	margin:0!important;\n	width:100%;\n	display:flex;\n	flex-wrap: wrap;\n	justify-content:space-around;\n	align-items:center;\n	\n	\n}\n\n.scp_item {\n	position:relative;\n	width:max(32vw, 440px);\n	aspect-ratio:4 / 3;\n	background-color:gray;\n	margin:2% 0;\n}\n\n.scp_item > img {\n	width:100%;\n	object-fit:cover;\n	height:100%;\n}\n\n.scp_black_creen {\n	position:absolute;\n	top:0;\n	width:100%;\n	height:100%;\n	background-color:RGBA(0,0,0,.3);\n		transition:0.2s;\n}\n\n.scp_read_more {\n	position:absolute;\n	background-color:white;\n	width:max(3.5vw,65px);\n	left:50%;\n	top:50%;\n	transform:translate(-50%, -50%);\n	aspect-ratio: 1 / 1;\n	display:flex;\n	justify-content:center;\n	align-items:center;\n	border-radius:200px;\n	line-height:1.2;\n}\n\n.scp_item_info {\n	position:absolute;\n	padding:5%;\n	width:50%;\n	height:40%;\n	top:0;\n	left:50%;\n	top:50%;\n	transform:translate(-50%, -50%);\n	display:flex;\n	flex-direction:column;\n	justify-content:space-between;\n	background-color:white;\n	transition:.5s;\n}\n\n.scp_item_info p {\n	margin:0!important;\n	padding:0!important;\n	text-align:center;\n	font-size:max(1vw,12px);\n	line-height:1.2;\n}\n\n.scp_item_info :nth-child(2){\n	color:gray;\n	font-size:max(.6vw,9px);\n}\n\n.scp_item > a {\n	display:block;\n	position:absolute;\n	top:0;\n	width:100%;\n	height:100%;\n}\n\n.scp_item:hover .scp_item_info{\n	opacity:0;\n	top:80%\n}\n\n.scp_item:hover .scp_black_creen {\n	opacity:0;\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>>> SECTION D*/\n\n.section_d {\n	position:relative;\n	width:100vw;\nheight:max(((900/1920)*100vw), 300px);\n		background-color:black;\n	min-width:1280px;\n	display:flex;\n}\n\n.section_d > .sd_carousel {\n	width:100%;\n	height:100%;\n	background-color:red;\n	o2verflow:hidden;\n	overflow-x:scroll;\n}\n\n.section_d > .sd_carousel > .sd_reel {\n	margin:0!important;\n	width:300%;\n	height:100%;\n	background-color:blue;\n	display:flex;\n}\n\n.section_d > .sd_carousel > .sd_reel > .sd_slide {\n	width:calc(100% / 3);\n	height:100%;\n	background-color:yellow;\n}\n\n.section_d > .sd_carousel > .sd_reel > .sd_slide > img {\n	width:100%;\n	height:100%;\n	object-fit:cover;\n	object-position:100% 100%;\n}\n\n\n\n\n\n\n\n\n\n\n\n\n.sd_info_container {\n	width:50%;\n	left:50%;\n	height:60%;\n	position: absolute;\n	top:50%;\n	transform:translate(-50%, -50%);\n	display:flex;\n	flex-direction:column;\n	justify-content:space-around;\n	align-items:center;\n}\n\n.sd_info_container > h2 {\n	color:white;\n	text-align:center;\n	font-size: max(.9vw,12px);\n	opacity:0.6;\n}\n\n.sd_info_container > p {\n	color:white;\n	text-align:center;\n	font-size: max(1.2vw,15px);\n	opacity:0.6;\n}\n\n.sd_info_container a {\n	display:block;\n	width:max(10vw,130px);\n	text-align:center;\n	text-decoration:none!important;\n	padding:max(.4vw, 6px);\n	color:white;\n	border-style:solid;\n	border-color:white;\n	border-width:1.5px;\n	font-size:max(.8vw, 13px);\n	opacity:0.6;\n}\n\n.sd_info_container a:hover {\n	color:white;\n	border-style:none;\n	background-color:#063b5a;\n	opacity:1;\n}\n\n\n\n\n\n\n\n\n\n\n\nfooter {\n	width:100vw;\n	min-width:1280px!important;\n}\n\n\n\n','astra','','inherit','closed','closed','','2571-revision-v1','','','2023-06-20 18:06:44','2023-06-20 18:06:44','',2571,'https://suministrossustentables.com/?p=3183',0,'revision','',0),
(3184,1,'2023-06-20 18:36:56','2023-06-20 18:36:56','function autoScrollFooterCarousel(){\r\n	//alert(\"Snipet funcionando\");\r\n	\r\n	const carouselContainer = document.querySelector(\'.sd_carousel\');\r\n	const reel = document.querySelector(\'.sd_reel\');\r\n 	const slides = Array.from(reel.children);\r\n	console.log(slides);\r\n	let slideObj = [];\r\n	\r\n	let i = 0\r\n	let x= 0\r\n	\r\n	function slideProt(index, offsetLeft, width) {\r\n		this.index = index;\r\n		this.offsetLeft = offsetLeft;\r\n		this.width = width;\r\n		this.marginLeft = offsetLeft - (width / 2);\r\n		this.marginRight = offsetLeft + (width / 2);\r\n	};\r\n	\r\n	slides.forEach(slide=>{\r\n		slideObj[x] = new slideProt(i, slide.offsetLeft + (-(slides[0].offsetLeft)), slide.offsetWidth);			\r\n		x++\r\n		i++\r\n	});\r\n	\r\n	\r\n	\r\n	\r\n	let q = 1;\r\n	let intervalReelLoop =\"\"\r\n	\r\n	function reelAutoRun () { //Funcion para recorrer automaticamente el reel	\r\n		intervalReelLoop = setInterval(()=>{\r\n			if(q < 3){ \r\n				carouselContainer.scrollTo({\r\n					left: slideObj[q].offsetLeft,\r\n					behavior: \'smooth\'\r\n				});\r\n				q++\r\n			} else {\r\n				q = 0\r\n				carouselContainer.scrollTo({\r\n					left: 0,\r\n					behavior: \'smooth\'\r\n				});\r\n				q++\r\n			};		\r\n		},3500)\r\n	};\r\n	reelAutoRun()\r\n	\r\n	\r\n}\r\n\r\nautoScrollFooterCarousel()','Carusel_Seccion_2','','publish','closed','closed','','carusel_seccion_2','','','2024-02-26 21:47:17','2024-02-26 21:47:17','',0,'https://suministrossustentables.com/?post_type=wpcode&#038;p=3184',0,'wpcode','',0),
