gn:center;\n}\n\n.sc_portfolio_container {\n	padding:7% 0;\n	position:relative;\n	margin:0!important;\n	width:100%;\n	display:flex;\n	flex-wrap: wrap;\n	justify-content:space-around;\n	align-items:center;\n	\n	\n}\n\n.scp_item {\n	position:relative;\n	width:max(32vw, 440px);\n	aspect-ratio:4 / 3;\n	background-color:gray;\n	margin:2% 0;\n}\n\n.scp_item > img {\n	width:100%;\n	object-fit:cover;\n	height:100%;\n}\n\n.scp_black_creen {\n	position:absolute;\n	top:0;\n	width:100%;\n	height:100%;\n	background-color:RGBA(0,0,0,.3);\n		transition:0.2s;\n}\n\n.scp_read_more {\n	position:absolute;\n	background-color:white;\n	width:max(3.5vw,65px);\n	left:50%;\n	top:50%;\n	transform:translate(-50%, -50%);\n	aspect-ratio: 1 / 1;\n	display:flex;\n	justify-content:center;\n	align-items:center;\n	border-radius:200px;\n	line-height:1.2;\n}\n\n.scp_item_info {\n	position:absolute;\n	padding:5%;\n	width:50%;\n	height:40%;\n	top:0;\n	left:50%;\n	top:50%;\n	transform:translate(-50%, -50%);\n	display:flex;\n	flex-direction:column;\n	justify-content:space-between;\n	background-color:white;\n	transition:.5s;\n}\n\n.scp_item_info p {\n	margin:0!important;\n	padding:0!important;\n	text-align:center;\n	font-size:max(1vw,12px);\n	line-height:1.2;\n}\n\n.scp_item_info :nth-child(2){\n	color:gray;\n	font-size:max(.6vw,9px);\n}\n\n.scp_item > a {\n	display:block;\n	position:absolute;\n	top:0;\n	width:100%;\n	height:100%;\n}\n\n.scp_item:hover .scp_item_info{\n	opacity:0;\n	top:80%\n}\n\n.scp_item:hover .scp_black_creen {\n	opacity:0;\n}\n\n\n\n@media only screen and (max-width:1080px) {\n	.section_c {\n		padding:2% 8% 6%;\n		width:100vw;\n		min-width:300px!important;\n		background-color:whitesmoke;\n	}\n\n	.sc_title_container {\n		width:80%;\n		align-items:end;\n		height:initial;\n	}\n\n	.sc_title_container > img {\n		left:0%;\n		top:-10%;\n		height:120%;\n		opacity:.3;	\n	}\n\n	.sc_title_container > h2 {\n		font-size:max(4vw,12px);\n	}\n\n	.sc_portfolio_container {\n		padding:7% 0;\n		position:relative;\n		margin:0!important;\n		width:100%;\n		display:flex;\n		flex-wrap: wrap;\n		justify-content:space-around;\n		align-items:center;\n	}\n\n	.scp_item {\n		position:relative;\n		width:max(32vw, 440px);\n		aspect-ratio:4 / 3;\n		background-color:gray;\n		margin:2% 0;\n	}\n\n	.scp_item > img {\n		width:100%;\n		object-fit:cover;\n		height:100%;\n	}\n\n	.scp_black_creen {\n		position:absolute;\n		top:0;\n		width:100%;\n		height:100%;\n		background-color:RGBA(0,0,0,.3);\n		transition:0.2s;\n	}\n\n	.scp_read_more {\n		position:absolute;\n		background-color:white;\n		width:max(3.5vw,65px);\n		left:50%;\n		top:50%;\n		transform:translate(-50%, -50%);\n		aspect-ratio: 1 / 1;\n		display:flex;\n		justify-content:center;\n		align-items:center;\n		border-radius:200px;\n		line-height:1.2;\n	}\n\n	.scp_item_info {\n		position:absolute;\n		padding:5%;\n		width:50%;\n		height:40%;\n		top:0;\n		left:50%;\n		top:50%;\n		transform:translate(-50%, -50%);\n		display:flex;\n		flex-direction:column;\n		justify-content:space-between;\n		background-color:white;\n		transition:.5s;\n	}\n\n	.scp_item_info p {\n		margin:0!important;\n		padding:0!important;\n		text-align:center;\n		font-size:max(1vw,12px);\n		line-height:1.2;\n	}\n\n	.scp_item_info :nth-child(2){\n		color:gray;\n		font-size:max(.6vw,9px);\n	}\n\n	.scp_item > a {\n		display:block;\n		position:absolute;\n		top:0;\n		width:100%;\n		height:100%;\n	}\n\n	.scp_item:hover 	.scp_item_info{\n		opacity:0;\n		top:80%\n	}\n\n	.scp_item:hover .scp_black_creen {\n		opacity:0;\n	}\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>>> SECTION D*/\n\n.section_d {\n	position:relative;\n	width:100vw;\nheight:max(((700/1920)*100vw), 300px);\n		background-color:black;\n	min-width:1280px;\n	display:flex;\n}\n\n.section_d > .sd_carousel {\n	width:100%;\n	height:100%;\n	background-color:red;\n	o2verflow:hidden;	\n	overflow-x:scroll;\n	scroll-snap-type:x mandatory;\n	scroll-behavior: smooth;\n}\n\n.sd_carousel::-webkit-scrollbar {\n	display: none;\n}\n\n.section_d > .sd_carousel > .sd_reel {\n	margin:0!important;\n	width:300%;\n	height:100%;\n	background-color:blue;\n	display:flex;\n}\n\n.section_d > .sd_carousel > .sd_reel > .sd_slide {\n	width:calc(100% / 3);\n	height:100%;\n	background-color:yellow;\n	scroll-snap-stop: always;\n	scroll-snap-align: start;\n}\n\n.section_d > .sd_carousel > .sd_reel > .sd_slide > img {\n	width:100%;\n	height:100%;\n	object-fit:cover;\n	object-position:100% 100%;\n}\n\n.sd_black {\n	width:100%;\n	height:100%;\n	position:absolute;\n	background-color:black;\n	opacity:0.5;\n}\n\n\n\n\n\n\n\n\n\n\n\n.sd_info_container {\n	padding:2% 0%;\n	width:45%;\n	left:50%;\n	height:100%;\n	position: absolute;\n	top:50%;\n	transform:translate(-50%, -50%);\n	b2ackground-color:yellow;\n	display:flex;\n	flex-direction:column;\n	justify-content:end;\n	align-items:center;\n}\n\n.sd_info_container > h2 {\n	color:white;\n	text-align:center;\n	font-size: max(.9vw,12px);\n	opacity:0.6;\n}\n\n.sd_info_container > p {\n	color:white;\n	text-align:center;\n	line-height:1.4;\n	font-size: max(1vw,10px);\n	opacity:0.6;\n}\n\n.sd_info_container a {\n	display:block;\n	width:max(10vw,130px);\n	text-align:center;\n	text-decoration:none!important;\n	padding:max(.4vw, 6px);\n	color:white;\n	border-style:solid;\n	border-color:white;\n	border-width:1.5px;\n	font-size:max(.8vw, 13px);\n	opacity:0.6;\n}\n\n.sd_info_container a:hover {\n	color:white;\n	border-style:none;\n	background-color:#063b5a;\n	opacity:1;\n}\n\n\n@media only screen and (max-width:1080px) {\n	\n	.section_d {\n		width:100vw;\n	height:max(((1080/1920)*100vw), 200px);\n		min-width:300px;\n		display:flex;\n	}\n\n	.section_d > .sd_carousel {\n	}\n\n	.sd_carousel::-webkit-scrollbar {\n	display: none;\n	}\n\n	.section_d > .sd_carousel > .sd_reel {\n	}\n\n	.section_d > .sd_carousel > .sd_reel > .sd_slide {\n	}\n\n	.section_d > .sd_carousel > .sd_reel > .sd_slide > img {\n		object-position:50% 100%;\n	}\n\n.sd_black {\n	}\n	\n	.sd_info_container {\n		padding:2% 0%;\n		width:45%;\n		left:50%;\n		height:100%;\n		position: absolute;\n		top:50%;\n		transform:translate(-50%, -50%);\n		b2ackground-color:yellow;\n		display:flex;\n		flex-direction:column;\n		justify-content:end;\n		align-items:center;\n	}\n\n.sd_info_container > h2 {\n	color:white;\n	text-align:center;\n	font-size: max(.9vw,12px);\n	opacity:0.6;\n}\n\n	.sd_info_container > p {\n		line-height:1.4;\n		font-size: max(2vw,6px);\n		opacity:0.6;\n	}\n\n	.sd_info_container a {\n		width:max(15vw,70px);\n		text-decoration:none!important;\n		padding:max(1vw, 3px);\n		font-size:max(1.5vw, 7px);\n		opacity:0.6;\n	}\n\n.sd_info_container a:hover {\n	color:white;\n	border-style:none;\n	background-color:#063b5a;\n	opacity:1;\n}\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>>>>>>>>>FOOTER*/\n\nfooter {\n	width:100vw;\n	min-width:1280px!important;\n}\n\n@media only screen and (max-width:1080px) {\n		footer {\n			width:100vw;\n			min-width:300px!important;\n	}\n}\n\n\n\n','astra','','inherit','closed','closed','','2571-revision-v1','','','2023-06-21 18:10:50','2023-06-21 18:10:50','',2571,'https://suministrossustentables.com/?p=3313',0,'revision','',0),
(4107,1,'2023-11-19 16:45:08','2023-11-19 16:45:08','function openConnection(): mysqli\r\n{\r\n    try {\r\n        $conn = new mysqli(DB_HOST, DB_USER, DB_PASSWORD, DB_NAME);\r\n        if ($conn->connect_error) {\r\n            die(\"Error al abrir la conexión\");\r\n        }\r\n        $conn->set_charset(\'utf8\');\r\n        return $conn;\r\n    } catch (\\Throwable $th) {\r\n        die(\"Error al abrir la conexión\");\r\n    }\r\n}\r\n\r\nfunction query(string $query, mysqli $conn){\r\n    $result = $conn->query($query);\r\n    if(!$result && $conn->error){\r\n        echo \"<script>console.log($conn->error)</script>\";\r\n        die();\r\n    }\r\n    return $result;\r\n}\r\n\r\nfunction defineConstants()\r\n{\r\n    $conn = openConnection();\r\n    $result = $conn->query(\'select * from bltk_constants\');\r\n    while ($constant = $result->fetch_object()) {\r\n        define($constant->var, $constant->value);\r\n    }\r\n}\r\ndefineConstants();\r\n\r\nfunction getPostByName(string $postName,  mysqli $conn)\r\n{\r\n    $post = $conn->query(\"SELECT * FROM \" . POST_TABLE . \" WHERE post_name=\'$postName\' AND post_type=\'post\'\");\r\n    return $post->fetch_object();\r\n}\r\n\r\nfunction getPostMeta(int $postID, string $metaKey, mysqli $conn)\r\n{\r\n    $meta = $conn->query(\"SELECT * FROM \" . POSTMETA_TABLE . \" WHERE post_id=$postID and meta_key = \'$metaKey\'\");\r\n    return $meta->fetch_object();\r\n}\r\n\r\n\r\nfunction getPostByID(int $postID, mysqli $conn)\r\n{\r\n    $post = $conn->query(\"SELECT * FROM \" . POST_TABLE . \" WHERE ID=$postID\");\r\n    return $post->fetch_object();\r\n}\r\n\r\n\r\nfunction getLastPost(mysqli $conn, int $nth)\r\n{\r\n    //echo \"<script>console.log($nth)</script>\";\r\n    $post = $conn->query(\"SELECT * FROM \" . POST_TABLE . \" WHERE post_type=\'post\' and post_status=\'publish\' order by post_date desc limit $nth, 1;\");\r\n    return $post->fetch_object();\r\n}\r\n\r\nfunction getMostViewed(string $metaKey, mysqli $conn)\r\n{\r\n    $meta = $conn->query(\"SELECT * FROM \" . POSTMETA_TABLE . \" WHERE meta_key = \'$metaKey\'  ORDER BY meta_value DESC LIMIT 1\");\r\n    return $meta->fetch_object();\r\n}\r\n\r\n\r\nfunction itemMultilang($defaultContent, string $elementTable, int $elementId, string $colName, int $language, mysqli $conn)\r\n{\r\n    $element = $conn->query(\"SELECT * FROM \" . MULTILANG_TABLE . \" where table_name = \'$elementTable\' and element_id = $elementId and col_name = \'$colName\' and language = $language\")->fetch_object();\r\n\r\n    if ($element->content != \'\') {\r\n        return $element->content;\r\n    } else {\r\n        return $defaultContent;\r\n    };\r\n}\r\n\r\nfunction glbl_showcase_constructor(string $mainShowcaseName)\r\n{\r\n    $conn = openConnection();\r\n    $mainShowcase = query(\"SELECT * FROM \" . SHOWCASE_TABLE . \" WHERE name=\'$mainShowcaseName\' AND element_type=\'showcase\'\",$conn)->fetch_object();\r\n\r\n    $tag = $mainShowcase->tag_type;\r\n    $attributes = $mainShowcase->attributes;\r\n    $classes = \"class=\'$mainShowcase->classes\'\";\r\n\r\n    echo \"<$tag id=\'$mainShowcase->name\' $attributes $classes>\";\r\n    glbl_block_composer($mainShowcase, $conn);\r\n    echo \"</$tag>\";\r\n\r\n    $conn->close();\r\n}\r\n\r\nfunction glbl_block_composer(object $frame, mysqli $conn) {\r\n	$items = query(\"SELECT * FROM \" . SHOWCASE_TABLE . \" WHERE frame=\'$frame->ID\' ORDER BY PRIORITY\",$conn); //Hijos del $frame\r\n	\r\n	while($item = $items->fetch_object()) {\r\n		\r\n		if($item->tag_type <> \"\"){\r\n			\r\n			$function = $conn->query(\"SELECT function_name FROM \" . FUNCTIONS_TABLE . \" WHERE name=\'$item->tag_type\'\")->fetch_object()->function_name;\r\n			\r\n			$tag_obj->name = $item->tag_type;\r\n			$tag_obj->classes = $tag_obj->classes <> \"\" ? \"class= \'$item->classes\'\" : null;\r\n			$tag_obj->attributes = $item->attributes;\r\n			\r\n			$tag = $function($tag_obj);//$conn debe ser variable opcional\r\n		} else {\r\n			$tag->open = null;\r\n			$tag->close = null;\r\n		}\r\n		\r\n		echo $tag->open;\r\n		$function = $conn->query(\"SELECT function_name FROM \" . FUNCTIONS_TABLE . \" WHERE name=\'$item->element_type\'\")->fetch_object()->function_name;\r\n		$function($item,$conn);\r\n		echo $tag->close;\r\n	}\r\n}\r\n\r\n\r\nfunction glbl_tag_composer(object $tag_obj){\r\n	$tag->open = \"<$tag_obj->name $tag_obj->classes $tag_obj->attributes>\";\r\n	$tag->close = \"</$tag_obj->name>\";\r\n	\r\n	return $tag;\r\n}\r\n\r\nfunction glbl_img_tag_composer(object $tag_obj){//$conn debe ser variable opcional\r\n	$tag->open = \"<img $tag_obj->classes $tag_obj->attributes />\";\r\n	$tag->close = null;\r\n	\r\n	return $tag;\r\n}\r\n\r\nfunction glbl_item_composer(object $item, mysqli $conn) {\r\n\r\n	$col_name = $item->col_name;\r\n	$element = query(\"SELECT * FROM \" . GLOBAL_ITEMS_TABLE. \" WHERE id=\'$item->item_id\'\",$conn)->fetch_object();\r\n\r\n	$element->content = itemMultilang($element->$col_name, GLOBAL_ITEMS_TABLE, $element->id, $item->col_name, 2, $conn);//SE PASA POR EL MULTILANG\r\n\r\n	echo $element->content;\r\n}','global_funcs','','draft','closed','closed','','global_funcs','','','2024-02-28 18:08:47','2024-02-28 18:08:47','',0,'https://suministrossustentables.com/wpcode/global_funcs/',0,'wpcode','',0),
