(3980,3,'2023-07-28 00:56:40','2023-07-28 00:56:40','body {\n	--wp--custom--ast-content-width-size: 5000px!important;\n	overflow-x:auto!important;\n}\nimg {\n  max-width: 100%;\n}\n\n/*>>>>>>>>>>>MENU*/\n\n.menu_home {\n	padding:0 12%;\n	position:absolute;\n	z-index:1;\n	background-color:RGBA(70,150,40,0.8);\n	width:100vw;\n	display:flex;\n	justify-content:space-between;\n	min-width:1280px;\n	border-bottom-left-radius:100px;\n}\n\n.menu_home > a {\n	margin:0!important;\n	display:flex;\n	b2ackground-color:red;\n	height:max(3.3vw,43px);\n	align-items:center;\n}\n\n.burguer_menu {\n	display:none!important;\n}\n\n.menu_home > a > img {\n	height:80%;\n	object-fit:contain;\n}\n\n.menu_options {\n	margin:0!important;\n	padding:0!important;\n	b2ackground-color:red;\n	width:50%;\n	display:flex;\n	justify-content:space-between\n}\n\n.menu_options > a{\n	margin:0!important;\n	color:white;\n	width:25%;\n	justify-content:center;\n	align-items:center;\n	display:flex;\n	text-decoration:none!important;\n	font-family:Alata;\n	font-size:max(.6vw,11px);\n}\n\n.menu_active {\n	background-color:RGBA(0,0,0,0.3);\n}\n\n.menu_home a:hover {\n	background-color:RGBA(0,0,0,0.1);\n}\n\n\n\n@media only screen and (max-width:1080px) {\n	\n	.menu_home {\n		padding:0 12%;\n		justify-content:space-between;\n		min-width:300px;\n		border-bottom-left-radius:100px;\n	}\n\n	.menu_home > a {\n		height:max(7vw,25px);\n	}\n	\n	.burguer_menu {\n		display:flex!important;\n	}\n	\n	.burguer_menu:hover {\n		background-color:RGBA(0,0,0,0)!important;\n	}\n\n	.menu_home > a > img {\n	}\n\n	.menu_options {\n		display:none;\n	}\n\n	.menu_options > a{\n	}\n\n	.menu_active {\n	}\n\n	.menu_home a:hover {\n		background-color:RGBA(0,0,0,0.1);\n	}\n}\n\n/*>>>>>>>>>>>CARRUSEL*/\n@keyframes rotate {\n  0% { transform: rotate(0deg); }\n  25% { transform: rotate(-2deg); }\n  50% { transform: rotate(2deg); }\n  75% { transform: rotate(-2deg); }\n  100% { transform: rotate(0deg); }\n}\n\n.swiper-slide {\n  text-align: center;\n}\n.swiper-slide img:hover {\n  animation: rotate 0.5s ease alternate;\n  transition: all .3s;\n}\n.swiper-cards {\n  overflow: visible;\n}\n\n.swiper-pagination-bullet {\n  background-color: white;\n}\n\n.slide-legend {\n  text-align: center;\n  bottom: 0;\n  margin: 0;\n  background: white;\n  padding: 1.5rem 0;\n  transition: all 0.3s;\n  width: 100%;\n  border: 1px solid #e1e1e1;\n}\n\n.swiper-slide:hover .slide-legend {\n  height: unset;\n  padding: 1.5rem 0;\n}\n\n@media (max-width: 1280px) {\n  .swiper-cards {\n    overflow: hidden;\n  }\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>> SECTION A*/\n\n.section_a {\n	padding:0!important;\n	margin:0!important;\n	width:100vw;\n	height:100vh;\n	overflow:hidden;\n	min-width:1280px;\n	min-height:680px;\n	background-color:red;\n}\n\n.sa_block_1 {\n	position:relative;\n	width:100%;\n	height:70%;\n}\n\n.sa_carousel_home {\n	position:relative;\n	width:100%;\n	background-color:gray;\n	height:100%;\n	overflow-x:scroll;\n}\n\n.sa_carousel_home::-webkit-scrollbar {\n	display: none;\n}\n\n.sa_reel {\n	width:400%;\n	height:100%;\n	background-color:gray;\n	display:flex;\n}\n\n.sa_item {\n	width:calc(100%/4);\n	height:100%;\n}\n\n.sa_item > :nth-child(1){\n	width:100%;\n	height:100%;\n	object-fit:cover;\n	object-position:0% 30%!important;\n	filter:sepia(.6) contrast(1.4);\n}\n\n.sa_black_screen {\n	position:absolute;\n	top:0;\n	width:100%;\n	height:100%;\n	background-color:RGBA(0,0,0,0.5);\n}\n\n.sab1_info_container {\n	padding:0!;\n	position:absolute;\n	top:0;\n	left:25%;\n	transform:translatex(-50%);\n	height:70%;\n	aspect-ratio:6 / 4;\n	display:flex;\n	flex-direction:column;\n	justify-content:end;\n	align-items:center;\n	background-color:RGBA(0,0,0,0);\n		animation: fadeInOut 15s infinite;\n}\n\n.sab1_info_container > h2{\n	margin:0!important;\n	color:#9DF22F;\n	font-family:playfair display;\n	font-style:italic;\n	font-weight:500;\n	width:60%;\n	font-size:max(3vw,38px)\n}\n\n.sab1_info_container > p {\n	margin:1% 0!important;\n	paddin