(3948,1,'2023-07-27 00:04:09','2023-07-27 00:04:09','function openConnection($servername, $username, $password, $dbname): mysqli\r\n  {\r\n    try {\r\n      $conn = new mysqli($servername, $username, $password, $dbname);\r\n      if ($conn->connect_error) {\r\n        die(\"Error al abrir la conexión\");\r\n      }\r\n      $conn->set_charset(\'utf8\');\r\n      return $conn;\r\n    } catch (\\Throwable $th) {\r\n      die(\"Error al abrir la conexión\");\r\n    }\r\n  }\r\n\r\n  $conn = openConnection(\'localhost\', \'48fdda17a8\', \'6677ecbae566c4617d59\', \'993.c2a.mywebsitetransfer.com_1665427950\');\r\n  $carruseles = $conn->query(\"select * from carrusel_home\");\r\n  ?>\r\n\r\n<div class=\"container scp23e\">\r\n	  <div class=\"row justify-content-around gap-4\">\r\n\r\n      <?php while ($carrusel = $carruseles->fetch_assoc()) : ?>\r\n        <div class=\"col-12 col-md-5\" style=\"margin-bottom: 1.5rem;\">\r\n\r\n          <div class=\"swiper\">\r\n            <div class=\"swiper-wrapper\">\r\n\r\n              <?php\r\n              $slides = $conn->query(\"select * from carrusel_home_pics where carrusel_key = \" . $carrusel[\'id\']);\r\n              ?>\r\n\r\n              <?php while ($slide = $slides->fetch_assoc()) : ?>\r\n                <div class=\"swiper-slide\">\r\n                  <a href=\"<?php echo $carrusel[\'enlace\']; ?>\" target=\"_self\"><img src=\"<?php echo $slide[\"img_src\"]; ?>\" /></a>\r\n                </div>\r\n              <?php endwhile; //Fin del ciclo while \r\n              ?>\r\n\r\n            </div>\r\n            <!-- If we need pagination -->\r\n            <div class=\"swiper-pagination\"></div>\r\n          </div>\r\n\r\n          <p class=\"slide-legend\" style=\"margin-top: 0rem;\">\r\n            <?php echo $carrusel[\"descripcion\"] ?>\r\n          </p>\r\n        </div>\r\n\r\n      <?php endwhile; //Fin del ciclo while \r\n      ?>\r\n      \r\n    </div>\r\n</div>\r\n\r\n<script type=\"module\">\r\n    const swiper = new Swiper(\'.swiper\', {\r\n      // Optional parameters\r\n      direction: \'horizontal\',\r\n      loop: true,\r\n      effect: \'cards\',\r\n\r\n      // If we need pagination\r\n      pagination: {\r\n        el: \'.swiper-pagination\',\r\n      },\r\n\r\n      autoplay: true,\r\n    })\r\n  </script>\r\n\r\n<?php\r\n$conn->close();\r\n?>','carrusel_portafolio_scp23e','','publish','closed','closed','','carrusel_portafolio_scp23e','','','2024-02-28 18:08:49','2024-02-28 18:08:49','',0,'https://suministrossustentables.com/wpcode/carrusel_portafolio_scp23e/',0,'wpcode','',0),
