	padding:0;\n	margin:0;\n	background-color:#1d2832;\n	width:100vw;\n	height:120vh;\n	min-width:1280px;\n}\n\n.scp_phb1 > .frame {\n	background-color:RGBA(255,255,255,0.1);\n	width:100%;\n	aspect-ratio: 10 / 4;\n}\n\n.scp_phb1 > .frame > .img_frame {\n	width:100%;\n	height:100%;\n	b2ackground-color:red;\n}\n\n.scp_phb1 > .frame > .img_frame > img {\n	width:100%;\n	height:100%;\n	object-fit:cover;\n	object-position:50% 10%;\n	opacity:.8;\n	filter: grayscale(1);\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>>>>>>>>>FOOTER*/\n\nfooter {\n	width:100vw;\n	min-width:1280px!important;\n}\n\n@media only screen and (max-width:1080px) {\n		footer {\n			width:100vw;\n			min-width:300px!important;\n	}\n}\n\n\n\n','astra','','inherit','closed','closed','','2571-revision-v1','','','2023-08-02 05:56:15','2023-08-02 05:56:15','',2571,'https://suministrossustentables.com/?p=4087',0,'revision','',0);
