n	.section_z article > .asset 	{\n		left:-6%;\n		top:0%;\n		width:10%;\n		height:60%;\n		background: rgb(105,190,87);\nbackground: linear-gradient(0deg, rgba(105,190,87,1) 56%, rgba(104,255,0,0) 100%);\n	}\n} \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>>ARTICULO CSS*/\n\n\n.art_head {\n	b2ackground-color:blue;\n	m2argin:0!important;\n	width:1000px;\n	display: flex;\n	flex-direction:row-reverse;\n	justify-content:space-between;\n}\n\n.art_sidebar {\n	margin:0!important;\n	padding:2%;\n	width: 30%;\n	background-color:whitesmoke;\n}\n\n.art_sidebar :nth-child(1){\n	font-size:1.7vw;\n	font-weight:700;\n}\n\n.art_sidebar > p {\n	font-size:1vw;\n}\n\n\n\n\n.art_head > article {\n	margin:0!important;\n	padding:2%;\n	b2ackground-color:red;\n	width:65%;\n}\n\n.art_head > article > h1 {\n	font-family: playfair display;\n	font-size:5vw;\n	font-weight:700;\n	line-height:1;\n}\n\n.art_head > article > h2 {\n	font-size:1.2vw;\n	line-height:1.2;\n	font-weight:100!important;\n}\n\n.art_head > article > h3 {\n	font-size:1vw;\n	line-height:1.2;\n	font-weight:100!important;\n	color:gray;\n}\n\n.art_head > article > img {\n	width:100%;\n	aspect-ratio: 9 / 5;\n	object-fit:cover;\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>>>>>>>>>FOOTER*/\n\nfooter {\n	width:100vw;\n	min-width:1280px!important;\n}\n\n@media only screen and (max-width:1080px) {\n		footer {\n			width:100vw;\n			min-width:300px!important;\n	}\n}\n\n\n\n','astra','','inherit','closed','closed','','2571-revision-v1','','','2023-07-02 03:01:26','2023-07-02 03:01:26','',2571,'https://suministrossustentables.com/?p=3532',0,'revision','',0),
