:0;\n	padding:0;\n	margin:0;\n	background-color:#1d2832;\n	width:100vw;\n	height:120vh;\n	min-width:1280px;\n}\n\n.scp_phb1 > .frame {\n	background-color:RGBA(255,255,255,0.1);\n	width:100%;\n	aspect-ratio: 10 / 4;\n}\n\n.scp_phb1 > .frame > .img_frame {\n	width:100%;\n	height:100%;\n	b2ackground-color:red;\n}\n\n.scp_phb1 > .frame > .img_frame > img {\n	width:100%;\n	height:100%;\n	object-fit:cover;\n	object-position:50% 10%;\n	opacity:.8;\n	filter: grayscale(1);\n}\n\n/*PORTAFOLIO */\n.header {\n  text-align: center;\n}\n\n.header .name {\n  margin-top: 0.5rem;\n}\n\n.header img {\n  width: 4rem;\n  height: 4rem;\n  border-radius: 50%;\n}\n\n.header h1 {\n  font-size: 3rem;\n  max-width: 40%;\n  margin-left: auto;\n  margin-right: auto;\n  margin-top: 0.5rem;\n}\n\n.header .date {\n  margin-top: 0px;\n}\n\n.header .watermark {\n  position: absolute;\n  text-align: center;\n  z-index: -10;\n  top: 0;\n  left: 0;\n  right: 0;\n  color: #f8f9fd;\n}\n\n.header .watermark h1 {\n  font-size: 15rem;\n}\n\n@media (max-width: 1200px) {\n  .header .watermark h1 {\n    font-size: 5rem;\n  }\n}\n\n.divider {\n  margin-top: 0.5rem;\n  margin-bottom: 0.5rem;\n  margin-left: auto;\n  margin-right: auto;\n  width: 3.5rem;\n  height: 2px;\n  background-color: goldenrod;\n}\n\n.quote {\n  font-style: italic;\n  font-size: 2rem;\n  max-width: 50%;\n  margin-left: auto;\n  margin-right: auto;\n  text-align: center;\n  font-weight: bold;\n  line-height: 40px;\n}\n\n@media (max-width: 1200px) {\n  .quote {\n    max-width: 85%;\n  }\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>>>>>>>>>FOOTER*/\n\nfooter {\n	width:100vw;\n	min-width:1280px!important;\n}\n\n@media only screen and (max-width:1080px) {\n		footer {\n			width:100vw;\n			min-width:300px!important;\n	}\n}\n\n\n\n','astra','','inherit','closed','closed','','2571-revision-v1','','','2024-01-18 01:21:15','2024-01-18 01:21:15','',2571,'https://suministrossustentables.com/?p=4162',0,'revision','',0),
