	}\n\n.sd_black {\n	}\n	\n	.sd_info_container {\n		padding:2% 0%;\n		width:45%;\n		left:50%;\n		height:100%;\n		position: absolute;\n		top:50%;\n		transform:translate(-50%, -50%);\n		b2ackground-color:yellow;\n		display:flex;\n		flex-direction:column;\n		justify-content:end;\n		align-items:center;\n	}\n\n.sd_info_container > h2 {\n	color:white;\n	text-align:center;\n	font-size: max(.9vw,12px);\n	opacity:0.6;\n}\n\n	.sd_info_container > p {\n		line-height:1.4;\n		font-size: max(2vw,6px);\n		opacity:0.6;\n	}\n\n	.sd_info_container a {\n		display:none;\n		width:max(15vw,70px);\n		text-decoration:none!important;\n		padding:max(1vw, 3px);\n		font-size:max(1.5vw, 7px);\n		opacity:0.6;\n	}\n\n.sd_info_container a:hover {\n	color:white;\n	border-style:none;\n	background-color:#063b5a;\n	opacity:1;\n}\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>>> SECTION e*/\n\n.section_e{\n    display: grid;\n    place-items: center;\n    margin: 0;\n    padding: 0;\n    height: 100vh;\n    background: url(https://suministrossustentables.com/wp-content/uploads/2016/06/photo-1455348734739-11d7726c3c80.jpg);\n    background-size: cover;\n    background-repeat: no-repeat;\n    background-position: center;\n	min-width:1280px;\n}\n\n\n.form-dat{\n    background:#0c0c0c7b;\n    width: 30%;\n    position: absolute;\n    right: 10%;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    margin: 0;\n    padding-left: 0px;\n    padding-right: 20px;\n    border-radius: 20px;\n		padding-bottom: 30px;\n		padding-top: 30px;\n}\n\n.form-dat > p{\n    font-size: max(.8vw,11px);\n    margin-bottom: 15px;\n    color: #ffffff;\n		line-height:1.4;\n		text-align:center;\n}\n\n.form-dat form{\n    width: 80%;\n}\n\n.form-dat input{\n    font-size: 15px;\n    width: 100%;\n    padding: 10px;\n    margin-top: 25px;\n    border-top: none;\n    border-left: none;\n    border-right: none;\n    box-decoration-break: none;\n    outline: none;\n    background: none;\n    color: #ffffff;\