(3772,1,'2023-07-06 22:30:25','2023-07-06 22:30:25','echo \"<div class=\'scp_cm1\'>\r\n		<div class=\'container\'>\r\n			<a class=\'movil_sec_head\'>\r\n				Categorías\r\n				<img src=\'https://suministrossustentables.com/wp-content/uploads/2023/07/up-arrow-angle-1.png\' alt=\'\'/>\r\n			</a>\r\n		</div>\r\n	</div>\r\n	<script>\r\n		function movilCategory(){\r\n			const menuContainer = document.querySelector(\'.scp_cm1 > .container\');\r\n			const btnCategorias = document.querySelector(\'.movil_sec_head\');\r\n			const arrowBtn = document.querySelector(\'.movil_sec_head > img\');\r\n			\r\n			btnCategorias.addEventListener(\'click\',()=>{\r\n				arrowBtn.style.transform != \'rotate(0deg)\' ? arrowBtn.style.transform = \'rotate(0deg)\' : arrowBtn.style.transform = \'rotate(180deg)\';\r\n				menuContainer.style.maxHeight == \'1000px\' ? menuContainer.style.transition = \'ease-in-out .7s\' : menuContainer.style.transition = \'ease-in-out 1s\';\r\n				menuContainer.style.maxHeight == \'1000px\' ? menuContainer.style.maxHeight = \'max(10vw,30px)\' : menuContainer.style.maxHeight = \'1000px\';\r\n			})\r\n			\r\n			const mediaQuery = matchMedia(\'only screen and (max-width: 1080px)\');\r\n			mediaQuery.matches == false ? menuContainer.style.maxHeight == \'1000px\' : menuContainer.style.maxHeight = \'max(10vw,30px)\';\r\n			mediaQuery.matches == false ? btnCategorias.style.display = \'none\' : btnCategorias.style.display = \'flex\';\r\n			\r\n			mediaQuery.addListener(() => {\r\n				mediaQuery.matches == false ? menuContainer.style.maxHeight == \'1000px\' : menuContainer.style.maxHeight = \'max(10vw,30px)\';\r\n				mediaQuery.matches == false ? btnCategorias.style.display = \'none\' : btnCategorias.style.display = \'flex\';\r\n			});\r\n		};\r\n		movilCategory();\r\n	</script>\r\n\";		\r\n	$conex = mysqli_connect(\'localhost\',\'48fdda17a8\',\'6677ecbae566c4617d59\',\'993.c2a.mywebsitetransfer.com_1665427950\');\r\n	$conex->set_charset(\'utf8\');\r\n	\r\n	$consulta = mysqli_query($conex, \"SELECT * FROM wp_term_taxonomy WHERE taxonomy = \'category\' \");\r\n	while($fila = mysqli_fetch_assoc($consulta)) {\r\n		\r\n		$termID = $fila[\'term_id\'];\r\n		\r\n		$consulta2 = mysqli_query($conex, \"SELECT name FROM wp_terms WHERE term_id = \'$termID\' LIMIT 1\");\r\n		$termName = mysqli_num_rows($consulta2) > 0 ? mysqli_fetch_assoc($consulta2)[\'name\'] : \'\';\r\n		\r\n		$link = substr($_SERVER[REQUEST_URI],1,-1);\r\n		$query3 = mysqli_query($conex, \"SELECT ID FROM wp_posts WHERE post_name = \'$link\' LIMIT 1\");\r\n		$currentPostID = mysqli_num_rows($query3) > 0 ? mysqli_fetch_assoc($query3)[\'ID\'] : \'\';\r\n		\r\n		$currentCat = \'none\';\r\n		\r\n		$query4 = mysqli_query($conex, \"SELECT * FROM wp_term_relationships WHERE object_id = \'$currentPostID\' \");\r\n		if (mysqli_num_rows($query4) > 0) {\r\n			while($taxNumber = mysqli_fetch_assoc($query4)){\r\n				if($termID === $taxNumber[\'term_taxonomy_id\']) {\r\n					$currentCat = \'currentCategory\';\r\n				};\r\n			};\r\n		};\r\n		//echo $currentPostID;\r\n		\r\n		echo \"<script>\r\n				function appendCategorys(){\r\n					const categoryContainer = document.querySelector(\'.scp_cm1 > .container:nth-of-type(1)\');\r\n					const categItem = document.createElement(\'a\');\r\n					\r\n					categItem.classList.add(\'$currentCat\');\r\n					categItem.innerHTML = \'$termName\';\r\n					categItem.href = \'\'\r\n					categoryContainer.appendChild(categItem);\r\n				};\r\n				appendCategorys();\r\n			</script>\";\r\n	};','menu_categorias_articulos','','publish','closed','closed','','menu_categorias_articulos','','','2024-02-26 21:47:05','2024-02-26 21:47:05','',0,'https://suministrossustentables.com/wpcode/menu_categorias_articulos/',0,'wpcode','',0),
(3773,1,'2023-07-07 01:47:34','2023-07-07 01:47:34','<!-- wp:html -->\n<div class=\"art_head\">\n  <article>\n    <h1>¿Qué darle de comer a los peces?</h1>\n    <h2>La alimentación es uno de los aspectos más importantes en la acuicultura, ya que influye\ndirectamente en el crecimiento y salud de los peces.</h2>\n    <h3>30 de Febrero de 2023</h3>\n    <img src=\"https://suministrossustentables.com/wp-content/uploads/2023/07/Banner_Articulo_SUCCESS-1.png\" alt=\"\"/>\n  </article>\n\n  <div class=\"barra_lat\">\n     [wpcode id=\"3629\"]\n     [wpcode id=\"3707\"]\n  </div>\n</div>\n[wpcode id=\"3772\"]\n<!-- /wp:html -->','¿Qué darle de comer a los peces?','La alimentación es uno de los aspectos más importantes en la acuicultura, ya que influye directamente en el crecimiento y salud de los peces.','inherit','closed','closed','','3447-revision-v1','','','2023-07-07 01:47:34','2023-07-07 01:47:34','',3447,'https://suministrossustentables.com/?p=3773',0,'revision','',0),
