(4103,1,'2023-11-15 21:50:23','2023-11-15 21:50:23','function openConnection(): mysqli\r\n{\r\n    try {\r\n        $conn = new mysqli(DB_HOST, DB_USER, DB_PASSWORD, DB_NAME);\r\n        if ($conn->connect_error) {\r\n            die(\"Error al abrir la conexión\");\r\n        }\r\n        $conn->set_charset(\'utf8\');\r\n        return $conn;\r\n    } catch (\\Throwable $th) {\r\n        die(\"Error al abrir la conexión\");\r\n    }\r\n}\r\n\r\nfunction defineConstants() {\r\n	$conn = openConnection();\r\n	$result = $conn->query(\'select * from bltk_constants\');\r\n	while ($constant = $result->fetch_object()) {\r\n    	define($constant->var, $constant->value);\r\n	}\r\n}\r\n\r\ndefineConstants();\r\n\r\n\r\nfunction getPostByName($postTable, string $postName,  mysqli $conn)\r\n{\r\n$post = $conn->query(\"SELECT * FROM $postTable WHERE post_name=\'$postName\' AND post_type=\'post\'\");\r\nreturn $post->fetch_object();\r\n}\r\n\r\n\r\n\r\nfunction getPostMeta($metaTable, int $postID, string $metaKey, mysqli $conn)\r\n{\r\n$meta = $conn->query(\"SELECT * FROM $metaTable WHERE post_id=$postID and meta_key = \'$metaKey\'\");\r\nreturn $meta->fetch_object();\r\n}\r\n\r\n\r\n\r\nfunction getPostByID($postTable, int $postID, mysqli $conn)\r\n{\r\n$post = $conn->query(\"SELECT * FROM $postTable WHERE ID=$postID\");\r\nreturn $post->fetch_object();\r\n}\r\n\r\n\r\n\r\nfunction getLastPost($postTable, mysqli $conn, $nth)\r\n{\r\n//echo \"<script>console.log($nth)</script>\";\r\n$post = $conn->query(\"SELECT * FROM $postTable WHERE post_type=\'post\' and post_status=\'publish\' order by post_date desc limit $nth, 1;\");\r\nreturn $post->fetch_object();\r\n}\r\n\r\nfunction getMostViewed($metaTable, string $metaKey, mysqli $conn)\r\n{\r\n$meta = $conn->query(\"SELECT * FROM $metaTable WHERE meta_key = \'$metaKey\'  ORDER BY meta_value DESC LIMIT 1\");\r\nreturn $meta->fetch_object();\r\n}\r\n\r\n\r\n\r\nfunction itemMultilang($defaultContent, $multilangTable, $elementTable, $elementId, $colName, $language, $conn){\r\n$element = $conn->query(\"SELECT * FROM $multilangTable where table_name = \'$elementTable\' and element_id = $elementId and col_name = \'$colName\' and language = $language\")->fetch_object();\r\n\r\nif($element->content !=\'\' ){\r\n    return $element->content;\r\n}else {\r\n    return $defaultContent;\r\n};\r\n}\r\n','global_functions(deprecated)','','draft','closed','closed','','global_functions','','','2024-02-26 21:03:11','2024-02-26 21:03:11','',0,'https://suministrossustentables.com/wpcode/global_functions/',0,'wpcode','',0),
