(3850,1,'2023-07-08 17:54:29','2023-07-08 17:54:29','body {\n	--wp--custom--ast-content-width-size: 5000px!important;\n	overflow-x:auto!important;\n}\n\n/*>>>>>>>>>>>MENU*/\n\n.menu_home {\n	padding:0 12%;\n	position:absolute;\n	z-index:1;\n	background-color:RGBA(70,150,40,0.8);\n	width:100vw;\n	display:flex;\n	justify-content:space-between;\n	min-width:1280px;\n	border-bottom-left-radius:100px;\n}\n\n.menu_home > a {\n	margin:0!important;\n	display:flex;\n	b2ackground-color:red;\n	height:max(3.3vw,43px);\n	align-items:center;\n}\n\n.burguer_menu {\n	display:none!important;\n}\n\n.menu_home > a > img {\n	height:80%;\n	object-fit:contain;\n}\n\n.menu_options {\n	margin:0!important;\n	padding:0!important;\n	b2ackground-color:red;\n	width:50%;\n	display:flex;\n	justify-content:space-between\n}\n\n.menu_options > a{\n	margin:0!important;\n	color:white;\n	width:25%;\n	justify-content:center;\n	align-items:center;\n	display:flex;\n	text-decoration:none!important;\n	font-family:Alata;\n	font-size:max(.6vw,11px);\n}\n\n.menu_active {\n	background-color:RGBA(0,0,0,0.3);\n}\n\n.menu_home a:hover {\n	background-color:RGBA(0,0,0,0.1);\n}\n\n\n\n@media only screen and (max-width:1080px) {\n	\n	.menu_home {\n		padding:0 12%;\n		justify-content:space-between;\n		min-width:300px;\n		border-bottom-left-radius:100px;\n	}\n\n	.menu_home > a {\n		height:max(7vw,25px);\n	}\n	\n	.burguer_menu {\n		display:flex!important;\n	}\n	\n	.burguer_menu:hover {\n		background-color:RGBA(0,0,0,0)!important;\n	}\n\n	.menu_home > a > img {\n	}\n\n	.menu_options {\n		display:none;\n	}\n\n	.menu_options > a{\n	}\n\n	.menu_active {\n	}\n\n	.menu_home a:hover {\n		background-color:RGBA(0,0,0,0.1);\n	}\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>> SECTION A*/\n\n.section_a {\n	padding:0!important;\n	margin:0!important;\n	width:100vw;\n	height:100vh;\n	overflow:hidden;\n	min-width:1280px;\n	min-height:680px;\n	background-color:red;\n}\n\n.sa_block_1 {\n	position:relative;\n	width:100%;\n	height:70%;\n}\n\n.sa_