:0;\n	padding:0;\n	margin:0;\n	background-color:#1d2832;\n	width:100vw;\n	height:120vh;\n	min-width:1280px;\n}\n\n.scp_phb1 > .frame {\n	background-color:RGBA(255,255,255,0.1);\n	width:100%;\n	aspect-ratio: 10 / 4;\n}\n\n.scp_phb1 > .frame > .img_frame {\n	width:100%;\n	height:100%;\n	b2ackground-color:red;\n}\n\n.scp_phb1 > .frame > .img_frame > img {\n	width:100%;\n	height:100%;\n	object-fit:cover;\n	object-position:50% 10%;\n	opacity:.8;\n	filter: grayscale(1);\n}\n\n/*PORTAFOLIO */\n.header {\n  text-align: center;\n}\n\n.header .name {\n  margin-top: 0.5rem;\n}\n\n.header img {\n  width: 4rem;\n  height: 4rem;\n  border-radius: 50%;\n}\n\n.header h1 {\n  font-size: 3rem;\n  max-width: 40%;\n  margin-left: auto;\n  margin-right: auto;\n  margin-top: 0.5rem;\n}\n\n.header .date {\n  margin-top: 0px;\n}\n\n.header .watermark {\n  position: absolute;\n  text-align: center;\n  z-index: -10;\n  top: 0;\n  left: 0;\n  right: 0;\n}\n\n.header .watermark h1 {\n  font-size: 15rem;\n	color: green;\n	opacity:.1;\n}\n\n@media (max-width: 1200px) {\n  .header .watermark h1 {\n    font-size: 5rem;\n  }\n}\n\n.divider {\n  margin-top: 0.5rem;\n  margin-bottom: 0.5rem;\n  margin-left: auto;\n  margin-right: auto;\n  width: 3.5rem;\n  height: 2px;\n  background-color: goldenrod;\n}\n\n.quote {\n  font-style: italic;\n  font-size: 2rem;\n  max-width: 50%;\n  margin-left: auto;\n  margin-right: auto;\n  text-align: center;\n  font-weight: bold;\n  line-height: 40px;\n}\n\n@media (max-width: 1200px) {\n  .quote {\n    max-width: 85%;\n  }\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>>>>>>>>>FOOTER*/\n\nfooter {\n	width:100vw;\n	min-width:1280px!important;\n}\n\n@media only screen and (max-width:1080px) {\n		footer {\n			width:100vw;\n			min-width:300px!important;\n	}\n}\n\n\n\n','astra','','inherit','closed','closed','','2571-revision-v1','','','2024-02-05 18:31:59','2024-02-05 18:31:59','',2571,'https://suministrossustentables.com/?p=4274',0,'revision','',0),
(4045,1,'2023-07-29 20:44:44','2023-07-29 20:44:44','body {\n	--wp--custom--ast-content-width-size: 5000px!important;\n	overflow-x:auto!important;\n}\nimg {\n  max-width: 100%;\n}\n\n/*>>>>>>>>>>>MENU*/\n\n.menu_home {\n	padding:0 12%;\n	position:absolute;\n	z-index:1;\n	background-color:RGBA(70,150,40,0.8);\n	width:100vw;\n	display:flex;\n	justify-content:space-between;\n	min-width:1280px;\n	border-bottom-left-radius:100px;\n}\n\n.menu_home > a {\n	margin:0!important;\n	display:flex;\n	b2ackground-color:red;\n	height:max(3.3vw,43px);\n	align-items:center;\n}\n\n.burguer_menu {\n	display:none!important;\n}\n\n.menu_home > a > img {\n	height:80%;\n	object-fit:contain;\n}\n\n.menu_options {\n	margin:0!important;\n	padding:0!important;\n	b2ackground-color:red;\n	width:50%;\n	display:flex;\n	justify-content:space-between\n}\n\n.menu_options > a{\n	margin:0!important;\n	color:white;\n	width:25%;\n	justify-content:center;\n	align-items:center;\n	display:flex;\n	text-decoration:none!important;\n	font-family:Alata;\n	font-size:max(.6vw,11px);\n}\n\n.menu_active {\n	background-color:RGBA(0,0,0,0.3);\n}\n\n.menu_home a:hover {\n	background-color:RGBA(0,0,0,0.1);\n}\n\n\n\n@media only screen and (max-width:1080px) {\n	\n	.menu_home {\n		padding:0 12%;\n		justify-content:space-between;\n		min-width:300px;\n		border-bottom-left-radius:100px;\n	}\n\n	.menu_home > a {\n		height:max(7vw,25px);\n	}\n	\n	.burguer_menu {\n		display:flex!important;\n	}\n	\n	.burguer_menu:hover {\n		background-color:RGBA(0,0,0,0)!important;\n	}\n\n	.menu_home > a > img {\n	}\n\n	.menu_options {\n		display:none;\n	}\n\n	.menu_options > a{\n	}\n\n	.menu_active {\n	}\n\n	.menu_home a:hover {\n		background-color:RGBA(0,0,0,0.1);\n	}\n}\n\n/*>>>>>>>>>>>CARRUSEL*/\n@keyframes rotate {\n  0% { transform: rotate(0deg); }\n  25% { transform: rotate(-2deg); }\n  50% { transform: rotate(2deg); }\n  75% { transform: rotate(-2deg); }\n  100% { transform: rotate(0deg); }\n}\n\n.swiper-slide {\n  text-align: center;\n