}\n.swiper-slide img:hover {\n  animation: rotate 0.5s ease alternate;\n  transition: all .3s;\n}\n.swiper-cards {\n  overflow: visible;\n}\n\n.swiper-pagination-bullet {\n  background-color: white;\n}\n\n.slide-legend {\n  text-align: center;\n  bottom: 0;\n  margin: 0;\n  background: white;\n  padding: 1.5rem 0;\n  transition: all 0.3s;\n  width: 100%;\n  border: 1px solid #e1e1e1;\n}\n\n.swiper-slide:hover .slide-legend {\n  height: unset;\n  padding: 1.5rem 0;\n}\n\n@media (max-width: 1280px) {\n  .swiper-cards {\n    overflow: hidden;\n  }\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>> SECTION A*/\n\n.section_a {\n	padding:0!important;\n	margin:0!important;\n	width:100vw;\n	height:100vh;\n	overflow:hidden;\n	min-width:1280px;\n	min-height:680px;\n	background-color:red;\n}\n\n.sa_block_1 {\n	position:relative;\n	width:100%;\n	height:70%;\n}\n\n.sa_carousel_home {\n	position:relative;\n	width:100%;\n	background-color:gray;\n	height:100%;\n	overflow-x:scroll;\n}\n\n.sa_carousel_home::-webkit-scrollbar {\n	display: none;\n}\n\n.sa_reel {\n	width:400%;\n	height:100%;\n	background-color:gray;\n	display:flex;\n}\n\n.sa_item {\n	width:calc(100%/4);\n	height:100%;\n}\n\n.sa_item > :nth-child(1){\n	width:100%;\n	height:100%;\n	object-fit:cover;\n	object-position:0% 30%!important;\n	filter:sepia(.6) contrast(1.4);\n}\n\n.sa_black_screen {\n	position:absolute;\n	top:0;\n	width:100%;\n	height:100%;\n	background-color:RGBA(0,0,0,0.5);\n}\n\n.sab1_info_container {\n	padding:0!;\n	position:absolute;\n	top:0;\n	left:25%;\n	transform:translatex(-50%);\n	height:70%;\n	aspect-ratio:6 / 4;\n	display:flex;\n	flex-direction:column;\n	justify-content:end;\n	align-items:center;\n	background-color:RGBA(0,0,0,0);\n		animation: fadeInOut 15s infinite;\n}\n\n.sab1_info_container > h2{\n	margin:0!important;\n	color:#9DF22F;\n	font-family:playfair display;\n	font-style:italic;\n	font-weight:500;\n	width:60%;\n	font-size:max(3vw,38px)\n}\n\n.sab1_info_container > p {\n	margin:1% 0!important;\n	padding:0!important;\n	width:60%;\n	color:white;\n	line-height:1.5;\n	font-size:max(.7vw,11px);\n}\n\n@keyframes fadeInOut {\n	from {opacity: 1;\n				left:25%}\n	50% {opacity: 1;\n			left:25%}\n	55% {opacity: 0;\n			left:50%}\n	95% {opacity:0;\n			left:50%}\n	to {opacity: 1;\n			left:25%}\n}\n\n.sa_block_1 > .slogan {\n	d2isplay:none;\n	width:100%!important;\n	position:absolute;\n	top:93%;\n	left:0%;\n	text-align:center;\n	t2ransform:translatex(-50%);	animation: sloganreel 15s infinite linear;\n	b2ackground-color:purple;\n}\n\n@keyframes sloganreel {\n	from { opacity:0}\n	50%{opacity:0}\n	55%{opacity:1}\n	85%{opacity:1}\n	95%{opacity:0}\n	to {opacity:0}\n}\n\n.sa_block_1 > .slogan > h2 {\n	width:100%;\n	color:white;\n	font-family:Playfair Display;\n	font-style:italic;\n	font-weight:500;\n	font-size:max(1.3vw,16px);\n	b2ackground-color:yellow;\n}\n\n\n.sa_block_2 {\n	position:relative;\n	width:100%;\n	height:30%;\n	background-color:white;\n	display:flex;\n	justify-content:space-between;\n	padding:2% 12%;\n}\n\n.sab2_info_container {\n	width:30%;\n	padding:2%;\n	b2ackground-color:red;\n	display:flex;\n	flex-direction:column;\n	justify-content:space-between;\n}\n\n.sab2_title_container{\n	display:flex;\n	height:20%;\n	j2ustify-content:c;\n	align-items:center;\n	margin-bottom:5%;\n}\n\n.sab2_title_container > img {\n	height:50%;\n	object-fit:contain;\n}\n\n.sab2_title_container > h2 {\n	font-size: max(1.2vw,16px);\n	margin:0 2%!important;\n}\n\n.sab2_info_container > p {\n	margin:0!important;\n	font-size: max(.7vw, 10px);\n	line-height:1.3;\n	text-align:justify;\n}\n\n\n\n\n@media only screen and (max-width:1080px){\n	\n	.section_a {\n		height:initial;\n		min-width:300px;\n		min-height:300px;\n		background-color:red;\n	}\n\n	.sa_block_1 {\n		width:100%;\n		aspect-ratio:1 / 1;\n	}\n\n	.sa_carousel_home {\n	}\n\n	.sa_reel {\n	}\n\n	.sa_item {\n	}\n\n	.sa_item > :nth-child(1){\n		object-position:50% 30%!important;\n	}\n\n	.sa_black_screen {\n		background-color:RGBA(0,0,0,0.42);\