olor:#69BE57;\n	content:\"\";\n	margin:0 .4vw 0 0!important;\n	height:max(.5vw, 5px);\n	aspect-ratio: 1 / 1;\n	border-radius:200px;\n}\n\n\n.scp_cm1:after {\n	margin:auto;\n	background: rgb(255,255,255);\nbackground: linear-gradient(90deg, rgba(255,255,255,1) 0%, rgba(162,240,71,1) 20%, rgba(105,190,87,1) 50%, rgba(128,215,79,1) 80%, rgba(255,255,255,1) 100%);\n	width:70%;\n	display:block;\n	height:1px;\n	opacity:.5;\n	content:\"\";\n}\n\n\n\n\n@media only screen and (max-width:1080px){\n	.scp_cm1{\n		margin-bottom:1.5%;\n		bwackground-	color:whitesmoke;\n		min-width:300px;\n	}\n\n	.scp_cm1 > .container {\n		margin:auto!important;\n		padding:0 12%;\n		b2ackground-color:blue;\n		width:100%;\n		h2eight:max(10vw,30px);\n		max-height:max(10vw,30px);\n		display:block;\n		flex-direction:initial;\n		justify-content:auto;\n		overflow:hidden;\n		transition:ease-in-out 1s;\n	}\n	\n	.movil_sec_head {\n		display:flex;\n		justify-content:space-between!important;\n		cursor: pointer;\n	}\n	\n	.movil_sec_head > img{\n		margin:0 2%;\n		height:20%;\n		filter:invert(30%);\n		transform:rotate(180deg);\n		transition:.5s;\n	}\n\n	.scp_cm1 > .container > a {\n		position:relative;\n		margin:1% auto!important;\n		width:50%;\n		height:max(10vw,30px);\n		text-decoration:none;\n		color:black;\n		display:flex;\n		justify-content:center;\n		b2ackground-color:red;\n		font-size:max(3vw,10px);\n		z-index:99;\n	}\n\n	.scp_cm1 > .container > .currentCategory:before {\n		display:block;\n		background-color:#69BE57;\n		content:\"\";\n		margin:0 .6vw 0 0!important;\n		height:max(.5vw, 5px);\n		aspect-ratio: 1 / 1;\n		border-radius:200px;\n	}\n\n\n	.scp_cm1:after {\n		margin:auto;\n		background: rgb(255,255,255);\n	background: linear-gradient(90deg, rgba(255,255,255,1) 0%, rgba(162,240,71,1) 20%, rgba(105,190,87,1) 50%, rgba(128,215,79,1) 80%, rgba(255,255,255,1) 100%);\n		width:70%;\n		display:block;\n		height:1px;\n		opacity:.5;\n		content:\"\";\n	}\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n