sidebar {\n	margin:0!important;\n	padding:2%;\n	width: 30%;\n	background-color:whitesmoke;\n}\n\n.art_sidebar :nth-child(1){\n	font-size:1.7vw;\n	font-weight:700;\n}\n\n.art_sidebar > p {\n	font-size:1vw;\n}\n\n\n\n\n.art_head > article {\n	margin:0!important;\n	padding:2%;\n	b2ackground-color:red;\n	width:65%;\n}\n\n.art_head > article > h1 {\n	font-family: playfair display;\n	font-size:5vw;\n	font-weight:700;\n	line-height:1;\n}\n\n.art_head > article > h2 {\n	font-size:1.2vw;\n	line-height:1.2;\n	font-weight:100!important;\n}\n\n.art_head > article > h3 {\n	font-size:1vw;\n	line-height:1.2;\n	font-weight:100!important;\n	color:gray;\n}\n\n.art_head > article > img {\n	width:100%;\n	aspect-ratio: 9 / 5;\n	object-fit:cover;\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n/*>>>>>>>>>>>>>>>>>FOOTER*/\n\nfooter {\n	width:100vw;\n	min-width:1280px!important;\n}\n\n@media only screen and (max-width:1080px) {\n		footer {\n			width:100vw;\n			min-width:300px!important;\n	}\n}\n\n\n\n','astra','','inherit','closed','closed','','2571-revision-v1','','','2023-07-02 23:28:17','2023-07-02 23:28:17','',2571,'https://suministrossustentables.com/?p=3581',0,'revision','',0),
(3583,1,'2023-07-02 23:45:58','2023-07-02 23:45:58','echo \"<div class=\'scp_pa7\'>\r\n		\r\n	  	<h2>Más populares</h2>\r\n	  	<div class=\'separator\'></div>\r\n		<div class=\'container\'>\r\n		</div>\r\n	</div>\";\r\n\r\n	$conex = mysqli_connect(\"localhost\",\"48fdda17a8\",\"6677ecbae566c4617d59\",\"993.c2a.mywebsitetransfer.com_1665427950\");\r\n	$conex->set_charset(\"utf8\");\r\n	\r\n	$consulta = \"SELECT * FROM wp_postmeta WHERE meta_key=\'views\' ORDER BY meta_value DESC LIMIT 5\";\r\n	$resultado = mysqli_query($conex, $consulta);\r\n	$numResultados = mysqli_num_rows($resultado);\r\n\r\n	if($numResultados > 0){\r\n		while ($fila = mysqli_fetch_assoc($resultado)){\r\n			$postID = $fila[\'post_id\'];\r\n			\r\n			$consultaThumbnail = \"SELECT * FROM wp_postmeta WHERE post_id=$postID and meta_key=\'_thumbnail_id\' LIMIT 1\";\r\n			$resThumbnail = mysqli_query($conex, $consultaThumbnail);\r\n			$thumbnailResultado = mysqli_num_rows($resThumbnail);			\r\n			\r\n			$filaThumb = mysqli_fetch_assoc($resThumbnail);\r\n			$thumbnailID = $filaThumb[\"meta_value\"];\r\n			\r\n			$consultaSrc = \"SELECT guid FROM wp_posts WHERE ID=$thumbnailID LIMIT 1\";\r\n			$resSrc = mysqli_query($conex, $consultaSrc);\r\n			\r\n			$filaSrc = mysqli_fetch_assoc($resSrc);\r\n			$thumbURL = $filaSrc[\"guid\"];\r\n			\r\n			$consultaPost = \"SELECT * FROM wp_posts WHERE ID = $postID AND post_type = \'post\' AND post_status = \'publish\' LIMIT 1\";\r\n			$resConsulta = mysqli_query($conex, $consultaPost);\r\n			\r\n			$filaPost = mysqli_fetch_assoc($resConsulta);\r\n			$postTitle = $filaPost[\'post_title\'];\r\n			$postExcerpt = substr($filaPost[\"post_excerpt\"],0,180).\'...\';\r\n			$postDate = date(\'d / M / Y\', strtotime($filaPost[\"post_date\"]));\r\n			$postGuid = \'https://suministrossustentables.com/\'.$filaPost[\"post_name\"];\r\n			\r\n			//echo \"$postTitle\".\" \";\r\n			\r\n			echo \"<script>\r\n				function loadViewedGalery() {\r\n					const container = document.querySelector(\'.scp_pa7 > .container\');\r\n					const item = document.createElement(\'div\');\r\n					const article = document.createElement(\'article\');\r\n					const postImg = document.createElement(\'img\');\r\n					const postTitle = document.createElement(\'h2\');\r\n					const postExcerpt = document.createElement(\'p\');\r\n					const postDate = document.createElement(\'h3\');\r\n					const postHref = document.createElement(\'a\');\r\n					\r\n					item.classList.add(\'item\');\r\n					postTitle.innerHTML = \".json_encode($postTitle).\"\r\n					postImg.src = \'$thumbURL\';\r\n					postExcerpt.innerHTML = \".json_encode($postExcerpt).\"\r\n					postDate.innerHTML = \'$postDate\';\r\n					postHref.href = \'$postGuid\';\r\n					\r\n					article.appendChild(postTitle);\r\n					article.appendChild(postExcerpt);\r\n					article.appendChild(postDate);\r\n					\r\n					item.appendChild(postImg);\r\n					item.appendChild(article);\r\n					item.appendChild(postHref);\r\n					\r\n					container.appendChild(item);	\r\n				};\r\n				loadViewedGalery();\r\n			</script>\";\r\n		};\r\n	};','most_viewed_posts_galery','','publish','closed','closed','','most_viewed_posts_galery','','','2024-02-26 21:47:13','2024-02-26 21:47:13','',0,'https://suministrossustentables.com/wpcode/most_viewed_posts_galery/',0,'wpcode','',0),
